quests[50421] = { id = 50421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparring auf der Spiere" }
quests[50432] = { id = 50432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanische Innovation", sourceObjective = "Spektakulär! Phänomenal! Die Titanen selbst sprechen zu mir und nun endlich begreife ich das große Ganze! Sie haben mich gelehrt, wie ich mithilfe dieser Essenzen die besten Rüstungen anfertigen kann, die diese Welt je gesehen hat!...Obwohl das Resultat nicht gänzlich... vorhersehbar ist.\n\n<Vridiel strahlt vor Stolz.>\n\nNun denn, worauf wartet Ihr? Bringt mir so viele erweckende Essenzen, wie Ihr finden könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[50433] = { id = 50433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treuer Rat ist teuer", description = "Ich würd ja gern sag'n, dass wir uns gut schlag'n, aber das tun wir nich'.\n\nDer Rat der Zanchuli is' gespalt'n. Raal un' ich sin' die Letzten, die König Rastakhan treu ergeben sin'. Überbringt die Nachricht Eurer Horde un' sagt den', was hier los is'.\n\nRaal un' ich versammeln, was wir an Verstärkung krieg'n könn', un' geh'n zum Zocalo.\n\nAch, un' <Held/Heldin>, danke, dass Ihr mir un' mei'm Loa das Leben gerettet habt.", sourceObjective = "Sprecht mit Baine Bluthuf in Dazar'alor.", completion = "Nur zwei ihrer sechs heiligsten Berater? Ich hatte gehofft, dass mehr von ihnen dem dunklen Pfad widerstanden hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50443] = { id = 50443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis zu den Wurzeln" }
quests[50444] = { id = 50444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falscher Fuffziger", description = "Diese Straße ist nich' mehr viel bereist. Außer von denen, die dem Blutloa dien'n. Dummköpfe also.\n\nIch will mein'n Spaß mit den Dummköpf'n ham. Geht zu dem Punkt, den ich für Euch markier', und legt da diese verfluchte Münze ab. Die dummen Bluttrolle werd'n sie seh'n und dann ham wir was zu lach'n, wenn sie versuch'n, sie aufzuheb'n.\n\nSorgt nur dafür, dass Ihr nicht geseh'n werdet. Sonst landet Ihr schnell wieder in den Armen von Jani.", sourceObjective = "Überlebt Janis Streich für die Amakitrolle.\n\nWenn Ihr Eure Sauridenverkleidung verliert, kehrt zu Jani zurück und besorgt Euch eine neue.", completion = "Haha! Gut gemacht, Zastamann. Diese Idioten werden ewig brauch'n, um aus dem Schlamassel wieder rauszukomm'n. Ihr seid in meiner Gunst gestieg'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50445] = { id = 50445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrollieren der Lage", description = "Ich habe diese makabre Armee aus Holz, Fleisch und Knochen beobachtet und dabei gesehen, wie die Hexen und Diener die niedereren Geschöpfe mithilfe von Talismanen kontrollieren. Ich sollte in der Lage sein, einen noch mächtigeren Talisman zu erschaffen, den wir für unsere Zwecke nutzen können.\n\nIn den Herzen der Diener findet man die stärksten Talismane. Sie dienen den uralten Drust als Anker für ihre körperliche Gestalt und sind genau das, was wir brauchen.\n\nViel Glück. Ich bezweifle, dass sie die so einfach hergeben werden.", sourceObjective = "Sammelt 5 Talismane der Kontrolle von den verhexten Bediensteten.", progress = "Konntet Ihr genug Talismane sammeln?", completion = "Ausgezeichnet. Ich sollte einige... interessante Dinge damit anstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[50446] = { id = 50446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenschießen", description = "Eine Donnerbüchse? Ich muss sagen, das habe ich wirklich nicht erwartet.\n\nDennoch, jetzt, da wir eine Waffe haben, sind wir im Vorteil. Ich glaube, es ist Zeit, dass wir den Kampf direkt zum Zirkel tragen.\n\nMarschall Lesner sagte mir, dass einige ihrer Matronen in Korlach gesehen wurden. Zeigen wir ihnen, was mit einem Feind des Hauses Kronsteig geschieht.", sourceObjective = "Benutzt Hexenschuss, um die Matronen Kerridwen, Adelina und Letizia in Korlach zu besiegen.", completion = "Hoffen wir, dass die Nachricht beim Zirkel angekommen ist. Solange wir über Waffen verfügen, um sie zu bekämpfen, werden wir standhaft bleiben.\n\nWo wir gerade von Waffen sprechen, ich glaube, unser Schmied hat eine Idee, wie man diese Barriere beseitigen kann. Ihr solltet Euch mit ihm unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50447] = { id = 50447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenken an die Gefallenen", description = "<Noch im Tode umklammert dieses Opfer eine Brosche, auf der etwas Ähnliches wie ein Familienwappen zu sehen ist. Anscheinend haben einige Dorfbewohner die Besetzung von Korlach durch den Zirkel nicht überlebt.\n\nEs ist vielleicht möglich, die Gefallenen anhand der Andenken, die sie bei sich tragen, zu identifizieren. Die Überlebenden wären womöglich dankbar, vom Schicksal der ihnen nahestehenden Personen zu erfahren.>", sourceObjective = "Sammelt 8 persönliche Andenken von gefallenen Einwohnern in Korlach.", progress = "Was haben wir denn hier?", completion = "Ich weiß nicht, was ich sagen soll. Ihr habt Euer Leben riskiert, um diese Gegenstände zu mir zu bringen, und das sagt einiges über Euren Charakter aus, Festländer.\n\nIch werde dafür sorgen, dass diese Andenken ihren Weg zu den Freunden und Familien der Gefallenen finden, damit sie von ihrem Schicksal erfahren. In ihrem Namen danke ich Euch für Euer Mitgefühl.", sourceObjectiveStatus = "unverified-source-field" }
quests[50448] = { id = 50448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korlach zurückerobern" }
quests[50449] = { id = 50449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkende Zuflucht", description = "Oh, gut, vielleicht könnt Ihr in dem hier einen Sinn erkennen.\n\nIch habe gerade eine Schneise in die Handlanger des Zirkels gemäht, als ich über dieses Feld gestolpert bin. Irgendetwas hier hat sie alle einfach umgehauen!\n\nIch kann die Ursache nicht finden, aber vielleicht habt Ihr mehr Glück. Ich bin eher daran gewöhnt, auf Dinge einzuschlagen, statt sie zu untersuchen.", sourceObjective = "Untersucht, was die Diener des Zirkels auf Hockes Beet ausgeschaltet hat.", completion = "Ihr seht nicht so aus, als ob Ihr mit dem Zirkel im Bunde steht, also was macht Ihr in Korlach?", sourceObjectiveStatus = "unverified-source-field" }
quests[50450] = { id = 50450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive Ernte", description = "Ihr wollt also mit dem Kronsteigmädchen den Kampf gegen den Zirkel aufnehmen, ja? Vielleicht könntet Ihr Euch deren offensichtliche Abneigung gegen Zwiebeln zunutze machen.\n\nWährend Ihr draußen auf den Feldern seid, haltet Ausschau nach Zwiebeln, die sich aus dem Boden wölben. Sie sollten ungewöhnlich aromatisch sein und unter den Dienern des Zirkels Krämpfe auslösen, wenn Ihr sie bei Euch tragt.\n\nNehmt nur nicht zu viele mit, einverstanden? Ich brauche noch genug auf den Feldern, damit mein Hof geschützt ist.", sourceObjective = "Sammelt 7 aromatische Zwiebeln von Hockes Beet.", progress = "Habt Ihr ein paar gute gefunden?", completion = "Die sollten Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50451] = { id = 50451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Verteidigung fressen", description = "Ich bin nicht sicher, wieso das so ist, und es ist mir eigentlich auch egal, aber aus irgendeinem Grund kann der Zirkel sich meinem Zwiebelfeld nicht nähern. Solange mir genug der Pflanzen bleiben, kann ich mich hier so lange es sein muss verschanzen.\n\nLeider hatten die Eber dieselbe Idee und fressen jetzt meine Ernte auf! Wenn sie so weitermachen, ist bald nichts mehr da, um den Zirkel fernzuhalten!\n\nWenn Ihr mir den Gefallen tut und ihre Zahl etwas ausdünnt, dürft Ihr gerne ein paar der Zwiebeln mitnehmen.", sourceObjective = "Tötet 8 gefräßige Eber auf Hockes Beet.", completion = "Das sollte eine Weile reichen.\n\nDanke für Eure Hilfe, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[50452] = { id = 50452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirkungsvoller Schutz", description = "Da, bitte. Ich habe die Zwiebeln ordentlich für Euch gebündelt.\n\nRichtet Fräulein Kronsteig meine Grüße aus, ja? Ihre Verbündeten sind jederzeit auf meinem Hof willkommen.", sourceObjective = "Bringt die Tasche mit aromatischen Zwiebeln zu Luzilla Kronsteig an der Wachmannshöhe.\n\nBereitgestellter Gegenstand:", completion = "Der Zirkel ist empfindlich gegen Zwiebeln?! Ich erinnere mich, dass meine Oma mir Geschichten erzählt hat, dass Zwiebeln das Böse abwehren, aber ich habe sie nie für bare Münze genommen!\n\nDas ist doch mal eine Entdeckung!", sourceObjectiveStatus = "unverified-source-field" }
quests[50453] = { id = 50453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrierenbrecher", description = "Hey, {name}! Ich glaube, ich habe eine Lösung für die lästige Barriere, die Euch den Weg ins Innere von Korlach versperrt!\n\nIch habe das Silber genommen, das wir noch hatten, und habe damit eine dieser Kanonenkugeln modifiziert. Die Mauern um Korlach sind mit Kanonen zur Verteidigung versehen. Zielt mit einer auf das Tor und Ihr könnt das Prachtstück hier mitten in die Barriere jagen!\n\nIhr braucht allerdings eine ordentliche Prise Sprengpulver, um die Kugel auf den Weg zu bringen... Sie ist ja doch recht schwer. Ihr könnt es wahrscheinlich in dem Lager außerhalb der Mauern finden.", sourceObjective = "Sammelt 5 Einheiten Sprengpulver an der Lanzenträgerklippe und bringt es zu Inquisitor Hartwasser vor dem Tor nach Oberkorlach.", progress = "Ich glaube, diese Jungs werden die Kanone nicht mehr brauchen.", completion = "Nettes Pülverchen, das Ihr da habt.\n\nSeid nur vorsichtig, dass Ihr nicht gleich die ganze Mauer einreißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50454] = { id = 50454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod eines Verräters", description = "Mir ist zu Ohren gekommen, dass Ihr einen Angriff auf das Lager vor den Mauern plant. Sollte das der Fall sein, habe ich eine Bitte.\n\nObwohl die meisten Wachleute, die gegen uns kämpfen, gegen ihren Willen vom Zirkel vereinnahmt wurden, haben Hauptmann Gutflink und seine Hellebardenbrigade ihre Seelen freiwillig dem Herzbann überlassen. Sie sind Verräter und eine Beleidigung für die Kronsteigwache.\n\nGutflink und seine Leute sind im Lager stationiert. Ihr würdet mir einen persönlichen Gefallen erweisen, wenn Ihr sie bis auf den letzten Mann niedermäht.", sourceObjective = "Tötet Hauptmann Gutflink.", completion = "Hauptmann Gutflink war ein Schandfleck auf dem Ruf der Kronsteigwache.\n\nIch hoffe, sein Ende war schmerzvoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[50455] = { id = 50455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nestflucht", description = "Es sieht so aus, als ob der Zirkel nicht alle unsere Falken bezaubern konnte. Ich sehe noch einige unverdorbene in Käfigen im Übungshof.\n\nUnsere Falken sind gut ausgebildet und müssten wissen, dass sie zu einem unserer anderen Höfe fliegen sollten, falls ihrem Falkner etwas zustößt.\n\nWenn Ihr sie nur aus ihren Käfigen befreit, müssten sie sich in Sicherheit bringen können.", sourceObjective = "Öffnet 5 Falkenkäfige in der Falknerei von Korlach.", completion = "Gute Arbeit! Mit ein wenig Glück sollten die Falken direkt in den Greifenhorst in Aroms Wehr zurückkehren.\n\nObwohl es mir ehrlich gesagt egal ist, wo sie sind, solange sie sich nicht in den Klauen des Zirkels befinden.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[50456] = { id = 50456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexte Küken", description = "Ich habe herausgefunden, wie diese bösen Hexen unsere Falken verdorben haben! Seht Ihr diese Talismane?\n\n<Nottlich zeigt auf die Hochstände und Dächer in der Nähe.>\n\nSie benutzen sie, um unseren Schwarm mit ihrer dunklen Magie zu infizieren, wenn die Jungen schlüpfen. Ich glaube, Wilhelm kann dort hinaufgelangen, um die Talismane zu entfernen, aber jemand muss ihm die Richtung weisen.\n\nIch habe mich noch nicht genug erholt, um mich mit einem ganzen Lager voller Falkner anzulegen. Könnt Ihr helfen?", sourceObjective = "Benutzt die Falknerpfeife, um 7 betörende Talismane in der Falknerei von Korlach zu zerstören.", completion = "Die Talismane sind zerstört? Welch eine Erleichterung!\n\nVielleicht können wir unseren Schwarm doch noch retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50457] = { id = 50457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzielt einen Durchbruch", description = "Die Kanone ist bereit, Boss.\n\nWollt Ihr das übernehmen?", sourceObjective = "Benutzt die Bollwerkkanone, um die Barriere am Tor nach Oberkorlach zu durchbrechen.", completion = "Ballasters Plan hat funktioniert! Er ist wirklich ein ideenreicher Schmied.\n\nKommt, Inquisitor. Das Kronsteiganwesen ist direkt voraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[50459] = { id = 50459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vugthuth" }
quests[50461] = { id = 50461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zujothgul" }
quests[50466] = { id = 50466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er ist verrückt geworden!", description = "Der alte Wildhauer hat jahrelang den Angriffen junger übereifriger und unterqualifizierter Jäger widerstanden.\n\nNiemand konnte ihn zur Strecke bringen.\n\nSeine Wunden haben ihm fast den Rest gegeben, aber er weigert sich, aufzugeben. Findet den verrückten Flussbestienbullen und helft ihm, seine sterbliche Hülle abzulegen.", sourceObjective = "Tötet Wildhauer.", completion = "Danke, dass Ihr ihn auf den Weg gebracht habt.\n\nWildhauer hat lange Jahre über diese Hügel gewacht. Ein Tier, das vorhat, in seine Fußstapf'n zu treten, wird es schwer hab'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[50468] = { id = 50468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shul-Nagruth" }
quests[50474] = { id = 50474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Andere Seite" }
quests[50476] = { id = 50476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling wartet", description = "{name},\n\nes gibt wichtige Dinge, die ich gern mit Euch besprechen würde, aber Diskretion ist das Allerwichtigste.\n\nSucht mich in meinen Gemächern in Unterstadt auf, wo ich sicher sein kann, dass unsere Privatsphäre nicht verletzt wird.\n\nVersichert Euch, dass Ihr nicht verfolgt werdet. In Orgrimmar wimmelt es nur so von SI:7-Spionen. Anscheinend wollen König Anduin und Mathias Shaw unbedingt unseren nächsten Schritt ausspähen. Wie bewundernswert.", sourceObjective = "Meldet Euch bei Kriegshäuptling Sylvanas Windläufer in Unterstadt.", completion = "Schön, dass Ihr es so schnell geschafft habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50481] = { id = 50481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Hallen des Drustkönigs", description = "In den Ruinen am Fuß dieses riesigen Baumes am See geht in letzter Zeit einiges vor sich. Was Meister Eschtal berichtet hat, entspricht der Wahrheit. Sie planen da unten etwas Großes.\n\nWir haben zwar ihr Ritual gestört, aber ich befürchte, es war zu spät.\n\nWir müssen dort hingehen. Falls noch etwas übrig ist, müssen wir es zerstören.", sourceObjective = "Stellt Gorak Tul.", progress = "Wir müssen Gorak Tul stellen.", completion = "Wir haben ihn verwundet, sonst hätte er sich nicht zurückgezogen. Unser Sieg wird aber nicht von langer Dauer sein, wenn wir uns nicht um seine Armee kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[50483] = { id = 50483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterfürst Xerxiz" }
