quests[50492] = { id = 50492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Truhe" }
quests[50493] = { id = 50493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rex holen", description = "Als dieses ganze Chaos hier ausbrach, ist Anselms Welpe davongelaufen. Er war zu Tode erschrocken!\n\nEin paar Landarbeiter sind aufgebrochen, ihn zu suchen, aber bei all diesen Monstrositäten, die den Hof terrorisieren, fürchte ich das Schlimmste!\n\nKönnt Ihr Ausschau nach Rex halten, wenn Ihr da draußen seid? Vielleicht ist er auch in dem Honig gefangen.", sourceObjective = "Brecht kristallisierten Honig auf, um nach Rex zu suchen.", completion = "Anselm wird sehr glücklich sein, dass Rex unversehrt geblieben ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[50496] = { id = 50496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glompschlund" }
