quests[50504] = { id = 50504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Honig glasierter Sven", description = "Ich glaube, ich habe da unten jemanden schreien gehört.\n\n{name}, da könnte es Ärger geben. Also los!", sourceObjective = "Rettet Sven Robertson.", completion = "Und ich dachte, mein letztes Stündlein hätte geschlagen!", sourceObjectiveStatus = "unverified-source-field" }
