quests[50529] = { id = 50529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister im Inneren" }
quests[50530] = { id = 50530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie verhext", description = "Wir müssen noch weitere Einwohner von Falkenforst retten, bevor sie geopfert werden.\n\nBefreit einfach alle, die Ihr findet.\n\nDer Schlüssel, mit dem wir Meister Eschtal befreit haben, sollte auch hier funktionieren. Viel Glück!", sourceObjective = "Befreit 10 gefangene Dorfbewohner.", completion = "Gut gemacht! Ihr habt nicht nur viele Unschuldige gerettet, sondern den Hexen auch den Nachschub für ihr Großritual verwehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50531] = { id = 50531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt vor der Nase", description = "Natürlich haben sie nicht für uns den Bestimmungsort auf den Kisten vermerkt.\n\nNichts ist jemals einfach, was?\n\nWenn sie die Waffen nicht auf Cassens' Fähre verladen, müssen sie durch Bronhavn hindurch. Der Frachthafen ist gleich da vorne die Straße hoch.\n\nBronhavn wird von einer Einheit Marinesoldaten der Prachtmeers geschützt. Aschenwind & Co. hat ganz schön Nerven, illegale Waffen direkt vor deren Nasen zu verschiffen.\n\nKommt, lasst uns mal einen Blick riskieren.", sourceObjective = "Sprecht mit Finn Schönwind in Bronhavn.", completion = "<Finn gibt vor, Euch nicht zu sehen, aber er flüstert Euch zu.>\n\nNatürlich ist sie es.", sourceObjectiveStatus = "unverified-source-field" }
quests[50533] = { id = 50533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf sie mit Gehölz!", description = "Wir haben das Großritual aufhalten können, aber wenn wir nichts unternehmen, werden es die Hexen erneut versuchen.\n\nWir müssen sie auslöschen. Restlos.\n\n<Morgenlicht lächelt.>\n\nWie freundlich von ihnen, dass sie uns die Mittel dafür zur Verfügung stellen.\n\nDank Euch haben wir es so weit geschafft, {name}. Ihr kontrolliert den Verwüster. Zerstört alles, was Euch in die Quere kommt! \n\nWenn wir fertig sind, können wir ein Signal senden, um uns hier rausholen zu lassen!", sourceObjective = "Verwendet den Blutholzverwüster, um die Hexenstreitkräfte im Blutroten Wald auszulöschen.", completion = "Wir haben die Pläne für das Großritual zunichtegemacht und die Ritualstätte zerstört. Meister Eschtal wird hier in Aroms Wehr in Sicherheit sein und wir können mit unseren Greifen endlich Verstärkung nach Falkenforst entsenden.\n\nSehr gute Arbeit! Ich danke Euch. Ihr wart eine sehr große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[50534] = { id = 50534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wendigo, leb wohl", description = "Dieses nächtliche unnatürliche Geheul aus dem Hochland deutet darauf hin, dass die Wendigos eine Art Anführer oder Alphatier haben müssen.\n\nIch sage Euch, das ist die Art Geräusch, die nur von einer riesigen, massigen und fleischfressenden Monstrosität stammen kann.\n\nGanz sicher eine Kreatur, die uns mühelos die Gliedmaßen abreißen kann, um genüsslich auf unseren zerbrechlichen Knochen zu kauen. Wie aufregend!\n\nAber ich bin mir dennoch sicher, dass wir mit ihr fertigwerden.", sourceObjective = "Tötet Knochenschinder.", completion = "Hervorragend! Es wird den anderen einen Schrecken eingejagt haben, dass wir ihren Anführer getötet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50535] = { id = 50535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht der Aufseherin", description = "Aufseherin Nerzet ist wahrlich grausam und sehr leicht zu provozieren!\n\nSie wird immer wütend, wenn etwas fehlt oder sich woanders befindet oder sich ändert... Meine Crew und ich leiden sehr unter ihr! Dass Ihr dieses Gerät zum Laufen gebracht habt, ist sicherlich von Vorteil!\n\nWir werden unsere Arbeit hier viel leichter abschließen können, sobald sie nicht mehr da ist.\n\nAch ja, vielleicht könntet Ihr ihr auch ihren schicken Machtstein abnehmen. Der könnte uns auch weiterhelfen.", sourceObjective = "Tötet Aufseherin Nerzet und nehmt ihr den Machtstein ab.", progress = "Konntet Ihr ihre Herrschaft beenden?", completion = "Hm... Er ist bestimmt wertvoll. Ich bin fast versucht, diesen Stein zu verkaufen.\n\nAber nach Eurer Vorstellung heute glaube ich, dass er von noch größerem Wert für uns ist, wenn wir ihn behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50536] = { id = 50536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisches Entschlüsselungsgerät", description = "Wir haben dieses Gerät von den Sethrak in den Ruinen im Osten sichern, aber noch nicht einsetzen können.\n\nAls Ihr näherkamt, fing es an zu leuchten. Ihr habt irgendeine Eigenschaft...\n\n<Maaz hält inne und betrachtet den Stein an Eurem Hals.>\n\n...oder tragt etwas bei Euch... was es aufweckt!\n\nBitte, {class}, verwendet das Szepter und untersucht die Statuen der Hüter auf dem zentralen Hof in den Ruinen. Irgendetwas dort hat ihre Aufseherin ganz schön in Aufregung versetzt.", sourceObjective = "Untersucht die Hüterstatuen in den Ruinen.", completion = "Oh, ich danke Euch, Giftnudel. Damit werden wir aus allem, was wir hier finden, den größten Nutzen ziehen können. Was für ein Glück, dass Ihr hergekommen seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[50538] = { id = 50538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Tierführer", description = "Ich hab gerade ausm Kriegsbestienkral gehört, dass einer ihrer Tierführer vermisst wird.\n\nDas is' normalerweise kein Problem, aber dieses Jahr erwart'n sie 'ne große Brut und werd'n alle Hände voll zu tun ham!\n\nGeht un' versucht, dies'n Tierführer zu find'n. Sein Name is' Bazo oder so. Sagt ihm, dass er zum Kral zurückkehr'n soll.", sourceObjective = "Sucht nach Tierführer Bazkoji in der Nähe des Kriegsbestienkrals.", completion = "<Tierführer Bazkoji ruht in Frieden, hält aber noch immer sein Schwert in der Hand. Er starb im Kampf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50539] = { id = 50539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Zul'Ahjin", description = "Es sind noch andere auf der Suche nach Antworten nach Zul'Ahjin gekommen. Hier wimmelt es nur so von Plünderern und Meuchelmördern, die alle irgendetwas suchen... \n\nBis jetzt haben sie noch nichts gefunden, weil sie nicht wissen, wo sie suchen sollen.\n\nAber ich weiß es. \n\nUntersucht die Statue in der Mitte der Ruinen. Sie ist der Schlüssel zu den uralten Geheimnissen der Stadt.", sourceObjective = "Untersucht die Statue.", completion = "<Die uralten Steine summen vor Magie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50540] = { id = 50540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft die Rastari zusammen" }
quests[50542] = { id = 50542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine explosive Gelegenheit", description = "Ihr da!\n\nIch habe eine FANTASTISCHE Gelegenheit für Euch! Ein Gnom namens Wulferd Zischkolben steht kurz vor einem Durchbruch, und braucht noch einen Geschäftspartner für die rustikalen Aspekte des Geschäfts. Also genau das Richtige für Euch, {class}!\n\nFolgt einfach der Straße nach Osten, bis Ihr Zischfeders Resort erreicht, ein fabelhaftes Wunder der Natur. Wulferd gehört zu den Leuten, die man nicht übersehen kann.", sourceObjective = "Sprecht mit Wulferd Zischkolben in Zischfeders Resort.", completion = "Ihr wollt mir freiwillig helfen? Na, so ein Angebot kann ich ja wohl kaum ablehnen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[50544] = { id = 50544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jäger von Kenningers Jagdhütte", description = "HILFE GESUCHT!\n\nFür die bevorstehende Hauptsaison sucht Kenningers Jagdhütte nach Freizeitjägern, die helfen können, die vielen Bestellungen aus Boralus abzuarbeiten. Es handelt sich hierbei um Kurzzeitstellen, die nach Leistung entlohnt werden. \n\nKenningers Jagdhütte befindet sich an der Straße nach Süden gleich hinter der Mine. Bitte meldet Euch bei Alina Holsten.", sourceObjective = "Sprecht mit Alina Holsten.", completion = "Ihr kommt aus Bronhavn? Dann wollen wir Euch mal etwas zu tun geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50545] = { id = 50545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gabelblitz" }
quests[50547] = { id = 50547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Messer von Zul" }
quests[50548] = { id = 50548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollstrecker des Willens des Königs" }
quests[50549] = { id = 50549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolut barbarisch" }
quests[50550] = { id = 50550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Imperator Korthek", description = "Korthek rückt endlich an.\n\nEs ist viele Jahre her, dass ich ihm im Kampf gegenüberstand. Als er die Macht an sich riss, habe ich vor meinem Volk versagt. Das wird nicht noch einmal passieren.\n\nIch bin bereit, zu tun, was getan werden muss... was ich schon vor langer Zeit hätte tun sollen.\n\nWir müssen Korthek töten und seinen Schlüssel nehmen, um zu verhindern, dass er, Jakra'zet oder irgendwer sonst Mythrax jemals wieder erwecken kann.\n\nWenn Ihr bereit seid, treten wir ihm gemeinsam gegenüber.", sourceObjective = "Tötet Imperator Korthek.", completion = "Vergeudet jetzt bloß keine Zeit, indem Ihr um meinen alten Freund trauert. Sein törichter Kreuzzug hat uns ein noch größeres Problem beschert, das unsere volle Aufmerksamkeit erfordert, und zwar sofort.", sourceObjectiveStatus = "unverified-source-field" }
quests[50551] = { id = 50551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel von Sethraliss: Avatar des Loas", description = "Wir können nicht zulassen, dass Mythrax wieder Zerstörung über diese Welt bringt. \n\nWir brauchen unseren Loa mehr als je zuvor, aber sie ist noch nicht zu uns zurückgekehrt.\n\nDie Zeit ihrer Wiedergeburt ist verstrichen. Jemand oder etwas scheint ihr Erwachen zu verhindern.\n\nGeht an ihre Ruhestätte und seht, was ihr herausfinden könnt.", sourceObjective = "Betretet den Tempel von Sethraliss und heilt den Avatar des Loas.", completion = "Seht, {name}. Sethraliss ist zurückgekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50553] = { id = 50553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Labor", sourceObjective = "Trefft Euch mit Raimund Mildenhall in Raimunds Labor.", completion = "Das war doch mal ein Abenteuer, {name}.\n\nDas sollten wir nicht so schnell wiederholen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50559] = { id = 50559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außer Kontrolle" }
quests[50561] = { id = 50561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sulthis' Stein", description = "<Das uralte Reliquiar enthält einen einzelnen Stein, der vor magischer Energie summt. Vielleicht weiß Serrik, was das ist?>", sourceObjective = "Bringt Sulthis' Stein zu Serrik in Zul'Ahjin.", progress = "Was habt Ihr gefunden?", completion = "Dieser Stein... So einen habe ich schon einmal gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50562] = { id = 50562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions von Azeroth", description = "Helft Magni, indem Ihr 4 Azeritweltquests abschließt.", sourceObjective = "Schließt 4 Azeritweltquests ab.", completion = "Azeroth und ich danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
