quests[50572] = { id = 50572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiger Übergriff" }
quests[50573] = { id = 50573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitteilung der Verwaltung", description = "<Dieser Brief von Priscilla Aschenwind an ihre Angestellten scheint überall in der Gießerei ausgehängt zu sein.\n\nOffenbar waren Cassens' Informationen richtig und Aschenwind & Co. lässt seine Leute rund um die Uhr arbeiten.\n\nPriscilla erwähnt einen Schmiedemeister Heller und einen Vorarbeiter Willem. Sie haben vielleicht weitere Informationen über ihre Pläne.>", sourceObjective = "Besorgt Priscillas Befehle von Schmiedemeister Heller und Vorarbeiter Willem.", progress = "Habt Ihr etwas Nützliches da drin gefunden?", completion = "Die meisten Leute, die für die Handelskompanie Aschenwind arbeiten, wissen gar nicht, was für miese Typen das sind, oder sie haben keine andere Wahl.\n\nJe schneller wir Priscilla ausschalten, umso besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[50574] = { id = 50574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhaltungsmethoden" }
quests[50577] = { id = 50577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst" }
quests[50578] = { id = 50578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuter Ruin" }
quests[50581] = { id = 50581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftrollen und Schuppen" }
quests[50583] = { id = 50583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Anderen Seite", description = "Der Zirkel scheint Korlach als Operationsbasis zu benutzen. Wir schaffen es unmöglich durch ihre Reihen, wenn wir keine Hilfe von den anderen Inquisitoren bekommen.\n\nDie sitzen wohl immer noch jenseits der Mauer fest. \n\n{class}, es gibt drei kleine Tore entlang der Mauern in Korlach. Versucht, sie zu öffnen, damit unsere Verbündeten sich auf den Weg machen können.", sourceObjective = "Öffnet die Tore im Osten, Süden und Westen von Oberkorlach.", progress = "Was gibt es von den anderen Inquisitoren zu berichten?", completion = "Sind jetzt alle da?\n\nAlso gut, wir haben keine Zeit zu verlieren. Wir müssen zum Kronsteiganwesen reiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[50584] = { id = 50584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinöse Rituale", description = "Werft mal einen Blick auf den Platz, {class}.\n\n<Marschall Lesner zeigt in die Ferne, wo ein paar Jüngerinnen ein Ritual durchführen.>\n\nDer Zirkel scheint nunmehr nicht nur dunkle Konstrukte, sondern auch wahrhaft alptraumhafte Kreaturen mit ihren Ritualen heraufzubeschwören. Ich will gar nicht wissen, wozu diese Monster fähig sind. Wir sollten sie umgehend ausschalten.\n\nZum Glück scheinen sich die Jüngerinnen zu sehr auf ihren Zauber zu konzentrieren, um uns zu bemerken. Das könnt Ihr vielleicht zu Eurem Vorteil nutzen.", sourceObjective = "Tötet 4 verseuchte Schrecken in Oberkorlach.", progress = "Wurden die Monster ausgelöscht?", completion = "Ich bin froh, dass wir die Dinger aufhalten konnten, bevor der Zirkel sie auf die ahnungslosen Bürger von Drustvar losgelassen hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[50585] = { id = 50585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexekution", description = "Hier scheint der Zirkel seine neuen Akolythinnen auszubilden. Wenn es ihnen gelingt, immer mehr Nachwuchs zu gewinnen, werden unsere Bemühungen umsonst sein.\n\nIch kann Luzilla jetzt nicht alleinlassen, aber Ihr habt Eure beachtlichen Kampffähigkeiten schon bewiesen. \n\nStreckt sie nieder.", sourceObjective = "Tötet 13 Hexen des Herzbannzirkels in Oberkorlach.", completion = "Je weniger Hexen es auf dieser Welt gibt, desto ruhiger können die Bürger von Drustvar schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50586] = { id = 50586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Korlach", description = "<Das weggeworfene Tagebuch sieht aus, als würde es einem Bewohner von Oberkorlach gehören. Darin werden auch frühe Anzeichen einer Präsenz des Herzbannzirkels in Korlach beschrieben.\n\nVielleicht könnt Ihr noch mehr solcher Schriften finden und so die Ereignisse offenbaren, die zum jetzigen Zustand von Korlach geführt haben.>", sourceObjective = "Untersucht 6 Tagebücher von Bewohnern von Korlach in Oberkorlach.", completion = "Diese Geschichte... Das ist ein schreckliches Schicksal für meine Heimat...\n\nWir müssen das wieder in Ordnung bringen, {class}! Für die Leute von Korlach und ganz Drustvar!", sourceObjectiveStatus = "unverified-source-field" }
quests[50587] = { id = 50587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagative Gedanken" }
quests[50588] = { id = 50588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf das Anwesen", description = "Das ist unsere Chance. Das Kronsteiganwesen ist gleich da oben auf dem Hügel. Und da drinnen finden wir hoffentlich meine Mutter und meinen Vater. \n\nUnd wenn wir dort auch die \"Mutter\" finden, die diesen schrecklichen Zirkel anführt, werden wir sie bereuen lassen, dass sie nach Drustvar gekommen ist.\n\nWerdet Ihr mir dabei helfen, {class}?", sourceObjective = "Folgt Luzilla Kronsteig zum Kronsteiganwesen in Oberkorlach.", completion = "Tut mir leid... Das ist alles ein bisschen viel für mich...\n\nDanke, dass Ihr mich beschützt habt, {class}. Ich brauche jetzt wohl einen Moment für mich allein...", sourceObjectiveStatus = "unverified-source-field" }
quests[50591] = { id = 50591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenfleißig" }
quests[50592] = { id = 50592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winziger Schrecken" }
quests[50593] = { id = 50593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blutige Angelegenheit", description = "<Die Phiole ist mit einer zähen, blubbernden Substanz gefüllt. Sie ähnelt stark den lebenden Schrecken um Euch herum.\n\nSie scheint gegen das Gefäß anzukämpfen, als ob sie ausbrechen wollte. Pike wäre sicher an weiteren Proben interessiert.>", sourceObjective = "Sammelt 20 Gezeitenblut.", progress = "Was habt Ihr denn da?", completion = "Dieses Gezeitenblut ist mit dunkler Magie durchtränkt. Danke, dass Ihr es mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50594] = { id = 50594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter dem Schleier", description = "Wir müssen uns an Bord der Abgründigen Melodie begeben und die unzähligen Seelen dort retten, bevor sie auch im Schrein verschwinden. Doch während die Barriere steht, kommen wir nicht auf das Schiff.\n\nDie Gezeitenweisen nutzen eine verbotene Magie, um ihrem Willen Gestalt zu geben. Mit diesen Greifern halten sie die Barriere aufrecht.\n\nNehmt mein Leuchtfeuer und markiert damit jeden einzelnen Greifer, dann werde ich von hier aus die Vergeltung auf sie hinabregnen lassen.", sourceObjective = "Benutzt das abgründige Leuchtfeuer, um die windenden Greifer zu bannen.", completion = "Die Abgründige Melodie ist ungeschützt. Das ist unsere Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[50595] = { id = 50595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade", description = "Wir sind gerade noch rechtzeitig gekommen. Diese Monstrositäten haben schon die Docks erobert und nur wir leisten ihnen noch Widerstand!\n\nIhr müsst einige von ihnen beseitigen, bevor sie uns überwältigen. Wir haben hier schließlich keine Armee!", sourceObjective = "Tötet 8 Skelettmatrosen und 4 Seerufer der Gezeitenweisen.", completion = "Dank Euch haben wir die Lage noch unter Kontrolle, aber Samuel wird noch immer vermisst!", sourceObjectiveStatus = "unverified-source-field" }
quests[50596] = { id = 50596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeziefer beseitigen", description = "Davon abgesehen, dass der Aufseher vor Wut tobt und dieser \"Schlüssel\" nicht da ist, haben wir auch noch ein Ungezieferproblem.\n\nKleine miese Vulperadiebe, die immer wieder die Grabungsstätte plündern. Wir konnten einige von ihnen gefangen nehmen.\n\nWir lassen sie im oberen Teil der Grabungsstätte arbeiten, um sie für ihr Fehlverhalten büßen zu lassen. Aber ich halte eine dauerhafte Lösung für angebrachter. \n\nOh, bitte, mächtige Kobra, ehret uns, indem Ihr das Ungeziefer mit Eurem wirkungsvollsten Gift auslöscht!", sourceObjective = "Rettet 3 gefangene Ausgräber.", completion = "Eine sehr gelungene Rettungsaktion von Euch. Ich weiß gar nicht, ob Ihr so listig seid oder sie so dämlich sind. Aber es sieht gut aus für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[50598] = { id = 50598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalariimperium", description = "Unterstützt das Zandalariimperium in Zuldazar, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Zuldazar ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung des Zandalariimperiums abgeschloss'n habt, {name}.", completion = "Das Zandalariimperium dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50599] = { id = 50599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prachtmeeradmiralität", description = "Unterstützt die Prachtmeeradmiralität, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests im Tiragardesund ab.", completion = "Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[50600] = { id = 50600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Glutorden", description = "Unterstützt den Glutorden, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests in Drustvar ab.", completion = "Der Glutorden dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50601] = { id = 50601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sturmwacht", description = "Unterstützt die Sturmwacht, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt beliebige 4 Weltquests im Sturmsangtal ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Sturmwacht abgeschlossen habt, {name}.", completion = "Die Gezeiten erzählten von Euren Triumphen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50602] = { id = 50602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talanjis Expedition", description = "Unterstützt Talanjis Expedition, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 Weltquests von Talanjis Expedition ab.", completion = "Ich dank' Euch im Namen der Prinzessin.", sourceObjectiveStatus = "unverified-source-field" }
quests[50603] = { id = 50603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voldunai", description = "Unterstützt die Voldunai, indem Ihr 4 Weltquests abschließt.", sourceObjective = "Schließt 4 Weltquests der Voldunai ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Voldunai abgeschlossen habt, {name}.", completion = "Die Voldunai danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50604] = { id = 50604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollanische Sucher", description = "Unterstützt die Tortollaner, indem Ihr 3 Weltquests abschließt.", sourceObjective = "Schließt 3 Weltquests der Tortollaner ab.", progress = "{name}, kehrt zu mir zurück, wenn Ihr den Tortollanern geholfen habt.", completion = "Ihr Jungspunde versteht es immer wieder, mich zu überraschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50605] = { id = 50605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsanstrengungen der Allianz", description = "Unterstützt die Allianz, indem Ihr 4 Weltquests auf Zandalar oder besetzten Gebieten der Kriegsfronten abschließt.", sourceObjective = "Schließt 4 Weltquests auf Zandalar oder besetzten Gebieten der Kriegsfronten ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Allianz abgeschlossen habt, {name}.", completion = "Für die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[50606] = { id = 50606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsanstrengungen der Horde", description = "Unterstützt die Horde, indem Ihr 4 Weltquests in Kul Tiras oder besetzten Gebieten der Kriegsfronten abschließt.", sourceObjective = "Schließt 4 Weltquests in Kul Tiras oder besetzten Gebieten der Kriegsfronten ab.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Horde abgeschlossen habt, {name}.", completion = "Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[50608] = { id = 50608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Riten", description = "Die K'thir befanden sich mitten unter uns. Sie brachten unbeachtet die Saat ihrer düsteren Meister aus und wir haben nichts davon gemerkt.\n\nNun, da die Barriere um die Abgründige Melodie gefallen ist, kann ich hineinblicken. In ihrem Inneren gibt mein Volk sich dem Schatten hin!\n\nNehmt meinen Gezeitenkris. Seine Klinge ist mit geläutertem Gezeitenblut bedeckt. Setzt diesen Unholden und ihren widerwärtigen Ritualen ein Ende.", sourceObjective = "Tötet 15 K'thir und unterbrecht 6 Rituale.", completion = "Gut. Jeder Tod bringt dieses Tal einen Schritt näher an die Erlösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[50609] = { id = 50609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Schlund des Wahnsinns", description = "Samuel ist noch immer irgendwo dort draußen. Wir können ihn nicht einfach im Stich lassen!\n\nWenn er nicht bei den Nebelflutwerken war, muss er sich auf dem Schiff befinden. Ihr müsst ihn finden!", sourceObjective = "Findet Samuel Willem.", completion = "Ihr habt meinen Kopf wahrlich aus der Schlinge gezogen. Ich verdanke Euch mein Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50610] = { id = 50610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der aufziehende Sturm", description = "Diese Verderbtheit verstößt gegen jeden Schwur, den wir als Gezeitenweisen abgelegt haben. Unser Volk zu behüten... zu leiten und zu erhalten... unsere Schiffe zu stärken.\n\nDas ist pure Dunkelheit und sie muss vollständig ausgelöscht werden.\n\nBegebt Euch an Bord der Abgründigen Melodie und platziert diese Fokusruten an allen kritischen Stellen. Ich werde das Ritual vorbereiten.", sourceObjective = "Platziert 4 Fokusruten auf der Abgründigen Melodie.", completion = "Bringen wir es zu Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[50611] = { id = 50611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Sturms", description = "Ich weiß zwar nicht, was für Schrecken uns erwarten, doch die Abgründige Melodie darf niemals ihrer Schwester in den Schrein des Sturms folgen.\n\nWir werden diesen Monstern die Früchte ihrer Arbeit verwehren, indem wir sie mit der Magie verbrennen, die sie verderben wollten.\n\nDas Ritual ist bereit, doch wir müssen seine Energie durch etwas kanalisieren. Wärt Ihr damit einverstanden, meine Magie zu leiten?", sourceObjective = "Vernichtet die Abgründige Melodie.", progress = "Sagt, wenn Ihr bereit seid.", completion = "Ein grundlegender Schritt, doch unsere Arbeit ist noch lange nicht getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[50612] = { id = 50612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gespaltenes Haus", description = "Nicht alle vom Hause Sturmsang sind dem dunklen Pfad meines Fürsten gefolgt. Sie wissen nichts von seiner Verdorbenheit - so wie ich nichts davon wusste.\n\nDort drüben, den Hang hinauf, liegt Weisenwall. Es ist der Ort, an dem alle Gezeitenweisen lernen, mit der Macht des Meeres umzugehen.\n\nWir werden auf die Sturmwacht aufbauen und meine zerschmetterte Heimat wieder eins werden lassen. Wir werden alle retten, die gerettet werden möchten.\n\nDer Rest wird untergehen.", sourceObjective = "Trefft Euch mit Bruder Pike außerhalb von Weisenwall.", completion = "Mit etwas Glück werden wir hier diese Sache zu einem guten Ende bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50614] = { id = 50614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für das Meer", description = "Die Naga hier scheinen die Küstenlinie in Richtung Hügel verschieben zu wollen. Bis jetzt konnten wir sie am Strand aufhalten, aber sie haben mehr Elementare gebunden, als wir im Zaum halten können.\n\nOhne einen Gezeitenweisen können wir die Elementare nicht von ihren Bindungen befreien. Aber wir dürfen nicht zulassen, dass sie noch weiter vorandrängen. Die Geister der Meere dürfen nicht gefangen gehalten werden. Tötet sie, damit sie in das Meer zurückkehren können.", sourceObjective = "Tötet 6 gebundene Meereswogen.", completion = "Das sollte ihr Vorhaben etwas aufhalten. Ich danke Euch dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[50616] = { id = 50616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Verbindlichkeiten", description = "Die Nagazauberin, die diese Exkursion anführt, ist wohl gerade dabei, einen größeren Elementar zu binden. Wenn ihr das gelingt, werden wir auf jeden Fall unsere Stellung hier aufgeben müssen.\n\nGreift sie an. Vielleicht könnt Ihr sie ja überraschen und so das Ritual unterbinden. Schlagt dieser Schlangenplage den Kopf ab.", sourceObjective = "Tötet Binderin Sa'thress.", progress = "Ist die Meereshexe tot?", completion = "Ich weiß nicht, was das ist, aber es gefällt mir überhaupt nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50617] = { id = 50617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atul'Aman", description = "In unserer Abwesenheit haben Jakra'zet und seine Truppen angegriffen.\n\nSerrik hat tapfer gekämpft, aber es hat nicht gereicht. Die Schlüssel sind weg, und es ist nur eine Frage der Zeit, bis die Barriere zerstört ist.\n\nEure Freunde sind ihnen schon gefolgt.\n\nWir dürfen nicht zulassen, dass Jakra'zet Mythrax den Auflöser erweckt. Wir müssen ihn stoppen, bevor es zu spät ist!\n\nUns bleibt nicht viel Zeit.\n\nTrefft mich in Atul'Aman. Wir müssen Kaja und Rakera einholen und das Ritual aufhalten!", sourceObjective = "Trefft Vorrik in Atul'Aman.", completion = "Wir müssen uns beeilen. Eure Freunde sind schon im Inneren!", sourceObjectiveStatus = "unverified-source-field" }
quests[50619] = { id = 50619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf und ab" }
quests[50621] = { id = 50621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Netz gegangen", description = "Beim ersten Eintreffen der Nagatruppen befanden sich noch ein paar Boote der einheimischen Fischer auf See. Unsere Späher haben berichtet, dass die meisten von ihnen gefangen genommen und am Strand in Käfige gesperrt wurden.\n\nBefreit so viele von ihnen wie möglich und zeigt ihnen den Weg hierher. Wir werden sie bewaffnen und dann die Naga daran erinnern, dass es unklug ist, sich mit Seeleuten anzulegen!", sourceObjective = "Befreit 5 Dorfbewohner.", completion = "Mit so vielen Leuten sollten wir unsere Stellung hier halten können. Ruder und Fischernetze geben erstaunlich effektive Waffen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[50622] = { id = 50622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Deike wird es heikel", description = "Es ist noch ein Bauernhof übrig. Er befindet sich weit im Westen und ganz nah am Kral.\n\nDeike bewirtschaftet ihn ganz allein. Wenn es irgendwen schwer getroffen hat, dann sie. Der Hof liegt hinter dem am schwersten betroffenen Teil des Einsturzes, also achtet auf die Stacheleber.", sourceObjective = "Sucht auf Deikes Bauernhof nach Überlebenden.", completion = "Gut zu wissen, dass die anderen in Sicherheit sind. Aber das wird nicht lange so bleiben, wenn wir nicht etwas gegen diese Stacheleber tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[50625] = { id = 50625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SNGDungeons - BfA - Normaler Dungeon - Nter" }
