quests[50634] = { id = 50634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet unsere Schriftrollen!" }
quests[50635] = { id = 50635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wogende Gezeiten", description = "Ich bin keine Gezeitenweise, aber selbst ich kann sehen, dass das kein gutes Zeichen für die Bastion ist. \n\nEs gibt dort einen Tortollaner namens Rikal, der uns dabei hilft zu vereiteln, was auch immer die Naga vor dem Damm im Schilde führen. Er würde das sicher gerne sehen.", sourceObjective = "Sprecht mit Rikal in Fort Daelin.", completion = "Hm... Das ist beängstigend. Sehr beängstigend.", sourceObjectiveStatus = "unverified-source-field" }
quests[50636] = { id = 50636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravierende Bedrohung" }
quests[50639] = { id = 50639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kronsteiganwesen: Die gefallene Mutter", description = "Das ist alles ganz schön viel auf einmal...\n\nDer Marschall ist... nicht mehr? Meine Mutter ist... die Anführerin des Zirkels? Das ist einfach zu viel...\n\nAber wir sind zu weit gekommen, um jetzt noch umzukehren. Es ist klar, dass meine Mutter und mein Vater, so wie ich sie kannte, nicht mehr existieren. Wir müssen dieses Land von der Verderbnis befreien.\n\nWir müssen die Inquisitoren mitnehmen und uns auf zum Kronsteiganwesen machen. Wir werden das ein für alle Mal beenden.", sourceObjective = "Besiegt Lady Kronsteig im Kronsteiganwesen.", completion = "Ich bin nicht stolz auf das, was wir getan haben, aber für das Wohl von Drustvar war es notwendig.\n\nIch hoffe nur, dass die Opfer, die wir alle gebracht haben, am Ende nicht umsonst waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[50640] = { id = 50640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schweinsgalopp", description = "Nicht zu glauben, dass Ihr das Ding erledigen konntet. Ihr seid wirklich beeindruckend, wisst Ihr?\n\nAuf jeden Fall sollten wir mit unserem Bericht zurück zu Rosen. Wir sind zwar mitten im Kral und von wütenden Stachelebern umzingelt, aber ich habe einen Plan!\n\nEinige dieser Eber sind einigermaßen zahm, seit ich meine Rationen mit ihnen geteilt habe. Sie folgen mir überallhin. Ich wette, mit den beiden können wir hier hinausgaloppieren. Seid Ihr dabei?", sourceObjective = "Reitet auf einem bockigen Kampfeber aus dem Kral der Borstenrücken hinaus und erstattet Bürgermeisterin Rosen Bericht.", completion = "Calvin hat mich schon informiert, aber ich würde gerne Euren Bericht hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[50641] = { id = 50641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "Dieser Tempel ist unsere letzte Bastion gegen die Treulosen. Alle fähigen Kämpfer müssen ihn mit aller Macht verteidigen. \n\nWenn Ihr Eure Hilfe anbieten wollt, seid Ihr willkommen. \n\nWerft Euch in die Schlacht und schaltet so viele von ihnen aus wie möglich!", sourceObjective = "Tötet 10 treulose Angreifer in den Tempelhöfen.", completion = "Unser Tempel wird niemals in die Hände der Treulosen fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50642] = { id = 50642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Kriegshäuptling befiehlt", description = "Silithus. Darum geht es in diesem Spiel... Oder zumindest ist es das, was die Allianz glauben soll.\n\nUnd natürlich ist Azerit genauso mächtig, wie man sagt. Aber ich habe größere Pläne.\n\nHochfürst Saurfang führt seine Armee gegen Silithus. Zurzeit müsste er sich im nördlichen Brachland aufhalten. Ich möchte, dass Ihr ihn findet und ihm mitteilt, dass die Vorbereitungen abgeschlossen sind.\n\nVorbereitungen wofür, fragt Ihr? Nun, wir werden den Weltenbaum erobern.", sourceObjective = "Findet Saurfang im Nördlichen Brachland.", completion = "Ich habe auf Eure Ankunft gewartet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50644] = { id = 50644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Eindringlinge", description = "Während wir versuchen herauszufinden, was wir mit diesen Kanalisierern machen, müssen wir jede Gelegenheit nutzen, sie zu treffen.\n\nUnsere Männer könnten bei der Zurückeroberung der unteren Mauern Unterstützung brauchen. Tötet ein paar Naga für mich, okay?", sourceObjective = "Tötet 15 der Nagaeindringlinge am Fort Daelin.", completion = "Jeder tote Naga ist einer weniger, mit dem sich meine Männer herumschlagen müssen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50645] = { id = 50645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denn der Aalfisch, der hat Zähne", description = "Wenn Ihr mitspielt, können wir den Naga eine lustige Überraschung bereiten.\n\n<Rikal zieht langsam eine Schriftrolle hervor und wedelt damit vor Eurem Gesicht herum.>\n\nIch benötige aber ein paar Zähne von Meeresraubtieren für den Zauber. Glücklicherweise haben die Naga ein paar widerliche Aale mitgebracht. Bringt mir ein paar ihrer Reißzähne.", sourceObjective = "Sammelt 16 Abgrundaalzähne.", progress = "Ich bin ja so gespannt, ob das funktioniert!", completion = "Das ist genau, was ich brauche. Gebt mir einen Augenblick, um den Zauber vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50646] = { id = 50646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schneller Richtungswechsel", description = "Ich habe unseren Marsch stoppen lassen und auf die Nachricht gewartet, dass wir bereit sind, die Richtung zu ändern.\n\nNun folgen koordinierte, gleichzeitige Angriffe auf bedeutende Standorte im Eschental. Wenn wir schnell vorgehen, werden wir die gesamte Verteidigung der Kaldorei vernichten und einen Weg direkt bis zur Dunkelküste freikämpfen.\n\nSturmwind wird sicher Verstärkung schicken, um uns aufzuhalten. Wir müssen Teldrassil erobern, bevor sie ankommen.\n\nIch werde die Truppen umlenken. Trefft Euch mit unserem Agenten Lorash außerhalb von Astranaar. Er wird Euch alles Weitere erklären.", sourceObjective = "Findet Lorash in Astranaar.", completion = "Saurfang sagt, es ist so weit? Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[50647] = { id = 50647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder hat seinen Preis", description = "Hunderte Schurken haben bereits die Außenposten der Kaldorei im Eschental angegriffen. Auf mein Signal hin werden sie mit der nächsten Phase des Krieges beginnen: Chaos säen.\n\nMein Kollege ist nicht weit von hier gestorben, {name}, also könnte ich Eure Hilfe brauchen. Wenn wir unentdeckt bleiben, wird die Stadt den Angriff nicht einmal mitbekommen, bevor wir all ihre Wachen ausgeschaltet haben.\n\nIch habe ein Gift, das die Wachen schnell und geräuschlos töten kann. Wenn Ihr mir signalisiert, welche Ziele ich unbemerkt angreifen kann, werde ich sie ausschalten.\n\nWas meint Ihr dazu?", sourceObjective = "Arbeitet mit Lorash zusammen, um Astranaar zu entwaffnen.", completion = "Wir haben es geschafft! Hoffentlich ist es an den anderen Außenposten genauso gut gelaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50648] = { id = 50648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Toten und Blasen" }
quests[50649] = { id = 50649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Räubern rauben", description = "Die Naga nehmen sich einfach, was sie wollen, und scheren sich nicht drum, wem es gehört. Vielleicht sollten wir das auch einmal mit ihren Sachen machen.\n\nDie Zauberinnen verwenden mächtige Fokusse zur Verstärkung ihrer Zauber. Vielleicht könnte ich mit diesen Relikten auch mein eigenes Ritual verstärken.", sourceObjective = "Sammelt 7 Gezeitenleuchtfeuer.", progress = "Bitte lasst auf keinen Fall einen der Fokusse fallen. Ich weiß wirklich nicht, was dann passiert.", completion = "Ah! Die sind wirklich machtvoll! Sie werden mir eine große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[50650] = { id = 50650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung von Zalamar" }
quests[50651] = { id = 50651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potenzial unterbinden" }
quests[50652] = { id = 50652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand beißen, die sie füttert" }
quests[50653] = { id = 50653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedereroberung der Verteidigung", description = "Bis zum jüngsten Angriff konnten wir die Naga abwehren. Einige unserer Leute sind noch da draußen.\n\nDie Gezeitenmaiden foltern sie wohl langsam bis zum Tod. Wenn Ihr alle retten würdet, die Ihr nur könnt, dann wären wir wieder etwas näher dran, die Oberhand zurückzugewinnen.", sourceObjective = "Rettet 8 gestrandete Bataillonssoldaten.", completion = "Das sollte sie vorerst aufhalten. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[50656] = { id = 50656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riskante Rettung", description = "Die treulosen Eindringlinge sind gleich da vorn. \n\nWir wollten ihre Belagerung durchbrechen, indem wir ihr Lager in der Nacht angreifen. Aber sie wussten, dass wir kommen. \n\nUnsere Truppen wurden sofort überwältigt. \n\nWir haben den Rückzug angeordnet, aber nur wenige von uns haben es herausgeschafft. Und wir wissen nicht, was aus den anderen geworden ist...\n\nWir haben nicht mehr genug Leute für einen eigenen Rettungsversuch. Wir können es uns nicht leisten, noch weitere Kämpfer zu verlieren. \n\nIhr seid ihre einzige Hoffnung.", sourceObjective = "Befreit 4 Tempelverteidiger.", completion = "Wir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50660] = { id = 50660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensstrategie" }
quests[50665] = { id = 50665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt keine Bluttrollapokalypse" }
quests[50667] = { id = 50667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällig" }
quests[50668] = { id = 50668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Gezeiten des Krieges", description = "Champion, die Horde befindet sich jetzt im offenen Krieg mit der Allianz.\n\nUnser Erfolg in diesem Konflikt könnte von Euren Fähigkeiten abhängen.\n\nIch benötige Euch sofort in Orgrimmar für eine Mission von äußerster Dringlichkeit. Lasst mich nicht warten!", sourceObjective = "Sprecht mit Nathanos Pestrufer in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[50670] = { id = 50670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doug Test - Gossip Test 3" }
quests[50672] = { id = 50672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Munition nicht wählerisch", description = "Ein paar meiner Männer verlegen einige Kanonen runter zur Meereswand, um auf mögliche Rituale im Delta vorbereitet zu sein.\n\nWir könnten aber noch zusätzliche Munition brauchen, bevor wir uns aufteilen. Glücklicherweise können wir unsere Mörser mit den Nagaharpunen bestücken. Schaltet ihre Lanzenträger aus und bringt so viele Harpunen zurück, wie Ihr könnt.", sourceObjective = "Sammelt 20 Harpunen der Zeth'jir an der Küste südlich von Fort Daelin.", progress = "Wir können die Waffen der Naga gegen sie einsetzen!", completion = "Gut gemacht! Bleibt nur zu hoffen, dass sich diese Harpunen gut mit unseren Kanonen abfeuern lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50674] = { id = 50674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlistiges Piratengesindel", description = "Wir wehren die Eisenfluträuber schon seit Tagen ab, aber jetzt haben sie einen Ettin als Verstärkung hergebracht. Er darf die Stadt auf keinen Fall angreifen. \n\nEinige meiner besten Männer sind den Hügel hinauf und versuchen, ihn zu töten. Ihr macht einen recht fähigen Eindruck. Wärt Ihr bereit, ihnen dabei zu helfen?", sourceObjective = "Eliminiert Täuscher Tom.", completion = "Ihr habt Fähigkeiten, die wir brauchen könnten. Möchtet Ihr Euch uns anschließen und uns helfen, den Schatz vor den Eisenfluträubern zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[50675] = { id = 50675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger des verlorenen Schatzes", description = "Die Arbeiter graben da draußen rund um die Uhr, um den verlorenen Schatz zu finden. Wenn Ihr helfen mögt, kriegt Ihr den gleichen Anteil wie alle anderen ab.\n\nSprecht mit Nante, wenn Ihr mitmachen wollt.", sourceObjective = "Sprecht mit Nante.", completion = "Ich hab Euch diese Eisenfluträuber erledigen sehen. Wollt Ihr bei uns mitmachen?", sourceObjectiveStatus = "unverified-source-field" }
quests[50676] = { id = 50676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusstribut" }
quests[50679] = { id = 50679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schild durchbohren", description = "Ich habe mit Rikal gesprochen und der Tortollaner sagt, dass unser Problem im Delta womöglich gelöst werden kann, wenn es uns gelingt, die Magie der Naga gegen sie selbst zu richten.\n\nEin paar Zauberinnen an der Südküste besitzen einen Kanalisierungszauberstab, mit dem wir vielleicht die Ritualkanalisierung der Oberpriesterinnen unterbinden können. Findet einen davon und bringt ihn mir.", sourceObjective = "Findet eine intakte Kanalisierungsrute der Zeth'jir.", progress = "Diese Festung darf unter keinen Umständen fallen!", completion = "Selbst ich kann spüren, wie viel Macht dieses Ding in sich birgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50689] = { id = 50689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksgrube" }
quests[50690] = { id = 50690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schimmer von Hoffnung", description = "Diese allgegenwärtige Dunkelheit wirft immer noch ihre Schatten auf unser Land und beeinträchtigt unsere Ernte.\n\nSucht Keyrra Flammenzunge auf und seht zu, dass Ihr gemeinsam mit ihr Ordnung schafft.", sourceObjective = "Sucht Keyrra Flammenzunge auf.", completion = "Es gibt immer etwas zu tun, {name}. Eure Hilfe beim Entzünden von zusätzlichen Schlüsselflammen würde Hoffnung bringen und vielen hier die Möglichkeit geben, wieder an die Arbeit zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50691] = { id = 50691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht für unser Geld", description = "Die Arbeiter beschweren sich, dass Elementare im Gebiet auftauchen, während sie nach Schätzen graben.\n\nErst heute Morgen wurden zwei meiner Leute zu Tode gequetscht. Das hält die Jagd auf!\n\nIhr könnt Euch etwas verdienen, indem Ihr diese lästigen Elementare beseitigt!", sourceObjective = "Vernichtet 10 ruhelose Steine.", completion = "Ich traue Euch fast, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50694] = { id = 50694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine blutige Angelegenheit", description = "Mein Orden segnet jedes Schiff von Kul Tiras in den Hallen im Schrein des Sturms. Unser Segen macht die Schiffe zu den stärksten in Azeroth, zu Schiffen der legendären Flotte.\n\nFür das Ritual brauchen wir eine Substanz, die man als Gezeitenblut kennt. Diese zähflüssige, mächtige Substanz wird aus den Tiefen des Meeres geborgen und im Rumpf jedes Schiffes verarbeitet.\n\nNun ist das Gezeitenblut hier aus irgendeinem Grund lebendig geworden. Wenn wir es genauer untersuchen, können wir unseren Feind womöglich besser verstehen.", sourceObjective = "Sammelt 20 Gezeitenblut.", progress = "Umso mehr Gezeitenblut Ihr beschaffen könnt, desto besser.", completion = "Danke. Das wird uns sicherlich helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50695] = { id = 50695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kannibalismus wird nicht geduldet" }
quests[50696] = { id = 50696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß mit Magneten", description = "Das letzte Mal musste ich Tol Barad rasch verlassen, doch auf meinem Weg habe ich mir ein paar Spielereien geschnappt. \n\nDieses Gerät ist mein Liebling, also seid vorsichtig damit! Das zieht die Schätze geradewegs aus dem Schlamm. Es prickelt vielleicht ein wenig, aber das hat nur mit der Strahlung zu tun.\n\nBenutzt den Metallsammler nahe der von mir platzierten Zeichen, um verlorene Münzen zu finden.", sourceObjective = "Sammelt 60 verlorene Münzen.", progress = "Ich mag Gold! Lasst uns etwas davon finden!", completion = "Ihr habt die Münzen und nur eine leichte Strahlenvergiftung.", sourceObjectiveStatus = "unverified-source-field" }
quests[50697] = { id = 50697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombe schlägt Stein", description = "Ich habe einem Eisenfluträuber eine alte Schatzkarte abgenommen. Auf der Karte sind mehrere Höhlen eingekreist.\n\nDiese Höhlen sind mit Felsbrocken versperrt, aber da Ihr jetzt hier seid, werden wir sie öffnen.\n\nIhr dürft all das gefährliche Zeug machen: Sprengladungen platzieren, alles Mögliche töten und Höhlen erkunden. Ich werde die Überwachung übernehmen.", sourceObjective = "Sprengt die östliche und die westliche Höhle auf!", completion = "Bumm! Problem gelöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[50698] = { id = 50698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problemlösung mit Schießpulver", description = "Die Festungsmauern reichen nicht als Verteidigung. Wir haben Kanonen positioniert, um auf die Naga zu feuern, wenn sie zu nah heranrücken. Aber wir müssen unsere Abwehr auch auf das Umland ausweiten.\n\nEs gibt ein paar gut geeignete Stellen weiter unten am Strand, wo man Fallen aufstellen kann. Auf die Naga wartet eine böse Überraschung!", sourceObjective = "Platziert 5 Sprengfallen.", completion = "Platziert einfach noch weitere Minen, wenn Ihr geeignete Stellen dafür findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[50699] = { id = 50699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiterrechte", description = "Hey, Ihr da! Seid Ihr auf der Suche nach Arbeit?\n\nIch hab zwar keinen Job für Euch, aber ich kann Euch nur raten, Euch von Algersons Sägewerk fernzuhalten!\n\nAlgerson verspricht gute Arbeit und gute Bezahlung, aber er ist ein dreckiger Lügner!\n\nDie Arbeitsbedingungen sind furchtbar, wir werden ständig angegriffen und Algerson kümmert das alles einen Dreck!\n\nWir kleinen Leute sind ihm schnurzpiepegal. An Eurer Stelle würde ich das Weite suchen!", sourceObjective = "Sprecht mit Mainhardt Algerson in Algersons Sägewerk.", completion = "Hallo! Willkommen in Algersons Sägewerk. Kann ich Euch vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[50700] = { id = 50700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Drust", description = "Vor ein paar Tagen hat eine Gruppe Allianzforscher, die sich selbst die \"Forscherliga\" nennen, einen Trupp Soldaten aus Kul Tiras in die alten Drustruinen weiter entlang der Straße geführt.\n\nWir haben seitdem nichts mehr von ihnen gehört und ich mache mir langsam Sorgen. Ich kann meinen Posten nicht verlassen. Könntet Ihr also bitte mal nach ihnen schauen?", sourceObjective = "Findet die Mitglieder der Forscherliga im Thovasbasislager.", completion = "Wir haben hier vielleicht ein klitzekleines Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[50702] = { id = 50702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jakra'zet besiegen", description = "Jakra'zet beschwört Mythrax den Auflöser!\n\nWir dürf'n nich' zulass'n, dass das Ritual fortgesetzt wird. Jakra'zet muss aufgehalt'n werden, bevor's zu spät is'!\n\nGeht voran, {name}. Wir folg'n Euch.\n\nLos geht's!", sourceObjective = "Besiegt Jakra'zet.", completion = "Ist 'n Wunder, dass wir überlebt hab'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[50703] = { id = 50703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde informieren", description = "General Jakra'zet wurde bezwung'n, doch seine Beschwörung von Mythrax is' trotz unsrer Mühen gelung'n.\n\nWenn Sethraliss uns nich' beigestand'n hätte, wär'n wir sicher nich' lebendig aus Atul'Aman rausgekomm'.\n\nWir müss'n unsre Verbündeten wiss'n lass'n, was in Vol'dun passiert is'.\n\nIch selbst werd mit Prinzessin Talanji sprech'n. Ihr solltet die Horde informier'n. Wir brauch'n so viel Hilfe wie möglich.\n\nIch bin sicher, wir werd'n uns erneut treff'n, {name}. War mir eine Ehre, an Eurer Seite zu kämpf'n.", sourceObjective = "Sprecht mit Baine Bluthuf.", completion = "Ich werde die Dunkle Fürstin sofort über Eure Aktivitäten in Vol'dun informieren. Sie wird wissen, wie wir am sinnvollsten gegen diese neue Bedrohung vorgehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[50704] = { id = 50704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watt man so findet", description = "Ich treibe nebenher ein wenig Handel und verkaufe gebrauchte Schiffsteile an die Andersonwerft.\n\nSeht bei Eurer Schatzsuche nach, ob Ihr ein paar brauchbare Teile aus dem Schlamm ziehen könnt, also Anker, Kanonen... solche Dinge!\n\nWir werden sie dann Anderson verkaufen und Euch am Gewinn beteiligen.", sourceObjective = "Findet 12 alte Wrackteile.", progress = "Schaut nach, was Ihr im Schlamm finden könnt.", completion = "Damit werden wir gutes Geld verdienen. Niemand wird wissen, dass es gebrauchte Teile sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[50705] = { id = 50705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dreiköpfige Schlange", description = "Jetzt, wo alle Vorbereitungen getroffen wurden, müssen wir uns mit der Hauptbedrohung auseinandersetzen.\n\nIhr könnt die gefundene Kanalisierungsrute gemeinsam mit dieser Schriftrolle von Rikal nutzen, um die Schilde der Nagaanführer im Delta zu durchbrechen.\n\nBeeilt Euch! Haltet sie auf, bevor sie die Beschwörung abschließen können!", sourceObjective = "Tötet drei Kanalisierer der Naga.", completion = "Nun, die Blase scheint fort zu sein, doch dieser Strudel gefällt mir ganz und gar nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50706] = { id = 50706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Deltas", description = "Die Stärksten der Offensive der Zeth'jir befinden sich jetzt gerade im Delta und warten auf den Abschluss des Beschwörungsrituals. Wenn wir ein paar von ihnen beseitigen können, würden wir vielleicht endlich die Oberhand gewinnen.\n\nGeht dort hinab und verbreitet so viel Chaos wie möglich!", sourceObjective = "Tötet 15 der Nagaeindringlinge am Abendflutdelta.", completion = "Gute Arbeit! Das sollte die Naga vorerst abschrecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[50717] = { id = 50717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mit mir, Troll" }
quests[50718] = { id = 50718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agent des Todes" }
quests[50733] = { id = 50733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Morgen", description = "Das Haus Sturmsang mag verloren sein, aber es gibt in diesem Tal immer noch so viel Hoffnung. \n\nSam wusste das von Anfang an.\n\nWir müssen der Sturmwacht weiterhin helfen, wie wir nur können. Überreste des Hauses sind überall verteilt, und wer auch immer diese Dunkelheit über es gebracht hat, ist auch da draußen.\n\nCarsten und die anderen werden genau wissen wollen, was hier geschehen ist. Wir sollten es gemeinsam berichten.", sourceObjective = "Trefft Taelia im Büro des Hafenmeisters in Boralus.", completion = "Ich habe bereits von den meisten Details berichtet. Die Sturmwacht wäre uns bei der Vereinigung von Kul Tiras ein unschätzbar wertvoller Verbündeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[50735] = { id = 50735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begräbniseinheit" }
quests[50737] = { id = 50737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sprecher müssen schweigen" }
quests[50738] = { id = 50738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft zur rechten Zeit", description = "Meinen Teil der Abmachung habe ich erfüllt, {race}.\n\nIch werde mir die anderen Außenposten ansehen und herausfinden, ob meine Brüder und Schwestern zurechtkommen. Trefft Euch mit dem Kriegshäuptling und sagt ihr, dass wir Astranaar gesichert haben. Wenn alles nach Plan verlaufen ist, sollte sie bereits auf dem Weg sein.\n\nOh, und versucht mir ein wenig des Ruhms zukommen zu lassen, ja? \n\n<Lorash grinst Euch an.>", sourceObjective = "Empfangt Kriegshäuptling Sylvanas Windläufer in Astranaar.", completion = "Das war ein perfekt ausgeführter Schlag, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50739] = { id = 50739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Freunde", description = "Der arme kleine Coda ist wirklich aufgewühlt, seit seine Freunde verschwunden sind. \n\nIch habe ihn hier ohnmächtig entdeckt. Er wurde wohl von einer dieser schrecklichen Wespen gestochen. Doch ein Tropfen unseres Sandstachelgegengifts hat Coda wieder auf die Beine gebracht!\n\nNehmt etwas davon mit und seht Euch nach anderen hilfebedürftigen kleinen Freunden um.", sourceObjective = "Rettet 7 Zobeliltisse.", completion = "Oh, ich bin so erleichtert! Wir müssen diese kleinen Kerle vor allem mit großen Stacheln dort draußen behüten. Da werde ich wohl ziemlich beschäftigt sein. \n\nEs würde uns sehr helfen, wenn Ihr auf Codas kleinen Bruder aufpassen würdet!\n\nEr heißt Poda!", sourceObjectiveStatus = "unverified-source-field" }
quests[50740] = { id = 50740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenposten von Zoram'gar", description = "Saurfang wird unsere Truppen hier stationieren, jetzt wo Astranaar uns gehört. Ich werde meine Jagd auf die einzige Kreatur fortsetzen, die unseren Marsch zum Sieg noch aufhalten kann: Malfurion Sturmgrimm.\n\nAls nächsten Schritt werden wir einen Stützpunkt am Rand der Dunkelküste einrichten. Kommandant Grimmfang vom Außenposten von Zoram'gar sollte dort eine Armee unterbringen können.\n\nInformiert ihn über unsere Ankunft und stellt sicher, dass die nötigen Vorbereitungen getroffen werden.", sourceObjective = "Trefft die notwendigen Vorbereitungen am Außenposten von Zoram'gar.", completion = "Eine Streitkraft dieser Größe ist lange nicht durch das Eschental gezogen. Ich hoffe, Zoram'gar ist darauf vorbereitet, die gewaltigen Truppen der Horde zu beherbergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50741] = { id = 50741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kröte geht flöten", description = "Da ist ein Tortollaner, der versucht, unseren Schatz zu stehlen! Er hält sich im Westen der Stadt auf. Er ist sehr neugierig. Vielleicht hat er schon etwas gefunden!\n\nSprecht mit Moxie und überlegt Euch, wie Ihr ihn loswerden könnt.", sourceObjective = "Sprecht mit Moxie.", completion = "Wurmfleisch für die Kiste voller Schätze! Seid Ihr sicher, dass Ihr kein Goblin seid?", sourceObjectiveStatus = "unverified-source-field" }
quests[50742] = { id = 50742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wie für uns bestellt", description = "<Das sind alle Schätze, die Klaas Mekkel bislang gefunden hat. Schön verpackt und bereit für den Abtransport. Es gleicht fast einer Einladung, Euch nach Herzenslust zu bedienen!\n\nUm so viel Beute zu tragen, werdet Ihr allerdings ein paar zusätzliche Hände brauchen. Es lassen sich bestimmt ein paar Schatzjäger in der Gegend der Totenschwemme finden.\n\nBittet Balduin die Spürnase, den zahnlosen Ede und Hacki die Häckslerin um Hilfe.>", sourceObjective = "Bringt drei Schatzjäger dazu, Euch zu helfen.", completion = "Ihr habt Klaas Mekkels Schätze geplündert? Wer ist jetzt der Pirat?!", sourceObjectiveStatus = "unverified-source-field" }
quests[50743] = { id = 50743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das unmittelbare Problem", description = "Ich habe einen meiner Leutnants, eine Frau namens Bauer, zur Fischersiedlung die Straße hinab ausgesandt. Wir haben gehört, dass die Naga sich in der Richtung an der Küste ausbreiten.\n\nWir brauchen unsere Streitkräfte aber so bald wie möglich wieder hier. Also geht bitte zu ihr, um die Bewohner der Siedlung zu unterstützen.", sourceObjective = "Sprecht mit Leutnant Bauer.", sourceObjectiveStatus = "unverified-source-field" }
quests[50744] = { id = 50744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Erinnerung auffrischen" }
quests[50745] = { id = 50745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Infiltration des Reichs", description = "Direkt hinter diesem Grat ruht das Herz des Reichs der Treulosen. Sobald wir dort sind, müssen wir uns schnell und leise bewegen, um nicht bemerkt zu werden.\n\nZum Glück ist meine frühere Unterkunft in der Nähe. Ich kenne einen Durchgang, mit dem wir in die Festung gelangen sollten, ohne auf viel Widerstand zu stoßen. Sprecht mit mir, sobald Ihr bereit seid, dann weise ich Euch den Weg.\n\n<Vorrik sieht sich argwöhnisch um.>\n\nIch hätte damit gerechnet, dass die Treulosen hier patrouillieren... Haltet auf dem Weg die Augen nach allem offen, was verdächtig aussieht.", sourceObjective = "Begleitet Vorrik zu seiner Zuflucht.", completion = "Es ist zwar ungewöhnlich, aber ich glaube, Sethraliss würde es bestimmt gern sehen, wenn ihr Schrein zum Schutz von Unschuldigen in Not benutzt würde.\n\nUnd wenn diese Vulpera gegen die Treulosen kämpfen, werden sie nützliche Verbündete sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[50746] = { id = 50746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krater erobert", sourceObjective = "Kehrt zu Vorrik zurück.", completion = "Ich kann die Kriegsschreie der Vulpera bis hierher hören. Offenbar haben uns Eure Freunde eine Gelegenheit verschafft. Wir sollten sie nicht verstreichen lassen.\n\nIch habe einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[50747] = { id = 50747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nutzloser Amani" }
quests[50748] = { id = 50748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht fallen lassen... noch nicht", description = "Die Treulosen bilden Pterrordaxe als Reittiere aus, um den Tod von oben auf uns herabregnen zu lassen.\n\nIhre Himmelsrufer haben eine Methode entwickelt, mit der sie die empfindliche Blitzmagie in leicht zerbrechlichen Kristallen einfangen können. Im einfachsten Sinne sind das Blitzbomben. Die Magie dahinter ist wirklich genial.\n\nUnd die Bomben werden uns besonders nützlich sein, wenn wir die Hilfe von Rakjan erhalten können, dem mächtigen und wilden Pterrordax oben auf der Spitze des Berges.\n\nBeschafft so viele, wie Ihr tragen könnt. Ich werde versuchen, Rakjan auf unsere Seite zu ziehen.", sourceObjective = "Sammelt 6 empfindliche Blitzbomben von den Treulosen.", progress = "Die Zahl der Treulosen scheint unendlich, also schnappt Euch so viele, wie Ihr tragen könnt.", completion = "Ausgezeichnet! Rakjan scheint uns helfen zu wollen, also werden wir die hier sicherlich gewinnbringend einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50749] = { id = 50749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostenloser Ritt", description = "Wenn ich während meiner Zeit in Vol'dun eins gelernt habe, dann ist es die Tatsache, dass man nie zu lange an einem Ort bleiben sollte. Das gilt ganz besonders, wenn Treulose im Spiel sind.\n\nWir haben hier ordentlich zugeschlagen. Verschwinden wir, bevor wir noch erwischt werden.\n\nIch habe ein Reittier besorgt, das uns schnell zu Meerah und den anderen in Vorriks Zuflucht zurückbringt. Und keine Sorge... Die Treulosen werden es nicht mehr brauchen.", sourceObjective = "Stehlt das Schlachtkroluskreittier und kehrt zu Meerah zurück.", completion = "Ich werde den Krolusk von einigen der Vulpera draußen unterbringen lassen, falls wir ihn noch mal brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50750] = { id = 50750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Imperator zur Weißglut bringen", description = "Offenbar habe ich Kortheks Feigheit unterschätzt. Ich hätte ihn hinter der Barriere erwartet, bereit, uns aufzulauern. Aber er versteckt sich weiterhin.\n\nDas verschafft uns etwas Zeit für Vorbereitungen. Wir sollten sie nicht verstreichen lassen.\n\nWährend ich diesen riesigen Kristallen Energie entziehe, müsst Ihr die Reihen der Treulosen hier lichten. Ich werde Euch einen machtvollen Segen gewähren, der Euch Eure Aufgabe schnell erledigen lässt.\n\nWenn Korthek auftaucht, wird er unsere ganze Aufmerksamkeit fordern.", sourceObjective = "Benutzt Vorriks Bollwerk, um 75 Treulose in den Geweihten Sanden zu besiegen.", completion = "Ausgezeichnet. Jetzt können wir uns ohne Ablenkungen um Imperator Korthek kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[50751] = { id = 50751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das belagerte Sanktum", description = "Ich fürchte, dass Imperator Korthek nicht gelogen hat, als er mit seinem törichten Plan prahlte.\n\nWenn General Jakra'zet in unserer Abwesenheit das Sanktum der Ergebenen angegriffen hat, ist es sehr wahrscheinlich, dass er nun alles Nötige hat, um Mythrax zu erwecken.\n\nWir müssen schleunigst zum Sanktum, um Jakra'zet aufzuhalten. Mythrax darf nicht wiedererweckt werden!", sourceObjective = "Trefft Euch mit Vorrik im Sanktum der Ergebenen.", completion = "Wir kommen zu spät. Die Schlüssel sind weg.\n\nSethraliss... Was habe ich getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[50752] = { id = 50752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte von Sethraliss", description = "Es mag Euch überraschen zu hören, dass die Treulosen uralte Relikte von Sethraliss horten. Aber seid Euch sicher, dass sie das nicht aus Ehrerbietung oder Respekt tun, wie es sich gehört.\n\nKortheks Brut wird nur von Gier und einem unersättlichen Streben nach Macht angetrieben. Sie entreißen den Relikten alle Magie, auch wenn sie sie dazu zerstören müssen.\n\nRettet die uralten Relikte von Sethraliss in den Geweihten Sanden in der Nähe. Wir werden sie in Ehren halten und im Sanktum der Ergebenen aufbewahren.", sourceObjective = "Beschafft den Schädel des ersten Himmelsrufers, das Bekenntnis der Wiedergeburt, Sethraliss' Sichtstein und das Blut des gefallenen Loas.", progress = "Habt Ihr die Artefakte?", completion = "Unglaublich! Ich weiß noch, als damals die ersten von ihnen gefunden wurden...\n\nIhr habt allen Anhängern von Sethraliss heute große Güte erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50753] = { id = 50753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den letzten Bot fressen die Würmer", description = "Es könnte Euch Tage kosten, so viel Fleisch zu sammeln, und so lange will ich nicht warten müssen. Wir werden meinen Lieblingsbot als Köder benutzen!\n\nSchickt Wach-E los, wenn Ihr Störungen im Schlamm ausmacht. Er wird genug Lärm machen, um alle Würmer rauszutreiben.\n\nIhr tötet dann die Würmer und holt das Fleisch. Ich werde das Ganze von hier aus beobachten.", sourceObjective = "Beschafft Schlammwurmfleisch für Maokka.", progress = "Habt Ihr schon das Fleisch?", completion = "Das wird eine schmackhafte Schlammwurmsuppe ergeben. Die Kiste mochte ich sowieso nie so richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[50754] = { id = 50754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe und Verlust", description = "Ich möchte Euch um einen Gefallen bitten... etwas Persönliches.\n\nNördlich von hier, gleich hinter Korlach, liegt die Fahlhainkapelle. Auf dem dortigen Friedhof ruht jemand, der... mir sehr wichtig ist.\n\nEs ist nun schon eine Weile her, dass ich zum Grab gekommen bin, und ich möchte ein Zeichen meines Respekts hinterlassen. Würdet Ihr bitte diese Blumen am Grabstein platzieren, wenn Ihr es zur Fahlhainkapelle schafft?\n\nSucht dort einfach nach dem frischesten Grab...", sourceObjective = "Platziert den purpurfarbenen Strauß am einfachen Grabstein an der Fahlhainkapelle.", completion = "Luzilla hat Euch geschickt? Ich bin erleichtert zu hören, dass sie noch lebt. \n\nIch heiße Alexander Trittwart. Ich bin... nun ja, ich war Luzillas Verlobter.", sourceObjectiveStatus = "unverified-source-field" }
quests[50755] = { id = 50755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelfutter", description = "Ich weiß nicht, warum ich mich dazu bereit erklärt habe. Wir sollten doch gar nicht plündern.\n\nKiro gab mir genaue Anweisungen. Ich sollte ins Becken gehen und die Bussarde füttern.\n\nIch kann erst wieder ins Lager zurück, wenn sie gefressen haben... Aber solange es im Becken noch von Sethrak wimmelt, kriegen mich keine zehn Pferde dort hin.\n\nHabt Ihr schon mal einen Bussard gefüttert? Ist wirklich ganz einfach, versprochen.\n\nIhr tötet etwas, sie fressen es, und das war's auch schon.", sourceObjective = "Tötet Tiere im Salzbecken, damit Mekarus Bussarde etwas zu fressen haben.", completion = "Ich glaube, so satt habe ich diese Bussarde noch nie erlebt. Wie viel habt Ihr ihnen bloß zu fressen gegeben? \n\nAch, es spielt keine Rolle. Ihr habt damit auf jeden Fall meinen Schweif gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[50756] = { id = 50756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterirdische Evakuierung" }
quests[50757] = { id = 50757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezähmtes Gemetzel", description = "Die Treulosen sind stark von ihren Krolusken abhängig. Sie nutzen sie als Reit- und Lasttiere, als Kampfgefährten und oftmals auch als Nahrungsmittel, um das Sethrakimperium voranzutreiben.\n\nWenn es uns gelänge, ihre Verbindung zu den Krolusken zu stören, würden wir damit ihrem ganzen Reich Sand ins Getriebe streuen. Wie heißt es doch so schön? Ein kaputtes Rad bringt die ganze Karawane zum Stillstand.\n\nSchaltet so viele ihrer Kroluskzähmer aus, wie Ihr könnt. Darunter werden sie länger leiden, als wenn wir einfach nur ihre Kroluske töten würden.", sourceObjective = "Tötet 8 Treulose in den Futtergruben.", completion = "Diese Wunde werden die Treulosen sehr lange lecken. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50758] = { id = 50758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerzhafte Erinnerungen", description = "Hier ist etwas Schreckliches geschehen. Es hat mich verflucht, für alle Ewigkeit an dieser Stelle zu wandeln.\n\nIch erinnere mich nur noch, dass Luzilla und ich heiraten sollten, doch stattdessen erwartete mich mein Ende.\n\nWenn Ihr Mitgefühl im Herzen tragt, dann helft mir bitte. Bringt in Erfahrung, was in jener Nacht geschah, damit ich von hier fortkomme.\n\nMeine stärksten Erinnerungen messen dem Ring, den ich an jenem Tag für Luzilla bei mir hatte, eine große Bedeutung bei. Findet ihn bei meinen Überresten, vielleicht kann er Euch zur Antwort führen.", sourceObjective = "Durchsucht die vergessenen Knochen in der Fahlhainkapelle nach Trittwarts Ring.", completion = "Willkommen, werter Herr!\n\nDie Zeremonie sollte beginnen, sobald Lord Kronsteig da ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[50759] = { id = 50759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spät dran", description = "Entschuldigt, aber ich mache mir ein wenig Sorgen wegen der Verspätung von Lord Kronsteig.\n\nIch bereite Euch nur ungerne zusätzliche Arbeit, aber würdet Ihr netterweise nach ihm sehen? Die Zeremonie kann ohne ihn nicht beginnen.\n\nIhr findet ihn ganz oben im Turm im Zimmer der Braut.", sourceObjective = "Sprecht mit Lord Arthur Kronsteig in der Fahlhainkapelle.", progress = "Es muss hier irgendwo sein...", completion = "Hervorragend. Ich brauche nur noch ein paar Minuten für diese Sache und komme dann runter.\n\nBitte richtet Luzilla und Alexander aus, dass ich gleich so weit bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[50760] = { id = 50760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von diesem Tage an", description = "Lord Kronsteig ist auf dem Weg? Hervorragend!\n\nIch danke Euch, <mein Herr/meine Dame>. Bitte nehmt Platz.", sourceObjective = "Nehmt Platz und schaut Euch die Hochzeitszeremonie in der Fahlhainkapelle an.", completion = "Was ist hier los?!", sourceObjectiveStatus = "unverified-source-field" }
quests[50761] = { id = 50761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut in der Kapelle", description = "<Mein Herr/Meine Dame>, Ihr habt mir bereits geholfen und ich flehe Euch an, es noch einmal zu tun.\n\nMeine Wachen sind gegen diese Briganten ganz klar in der Unterzahl, aber ich muss hierbleiben, um Luzilla zu beschützen. Ich würde also Euch bitten, beim Schutz der Gäste zu helfen.\n\nWäret Ihr dazu bereit?", sourceObjective = "Besiegt 10 Assassinen der Roten Hand in der Fahlhainkapelle.", progress = "Wir müssen diese Halunken zurückschlagen!", completion = "Gut gemacht! Meine Wachen scheinen dank Euch die Oberhand zu gewinnen.\n\nAber Moment... Wo ist Margarete?", sourceObjectiveStatus = "unverified-source-field" }
quests[50762] = { id = 50762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Lady", description = "Margarete ist gar nicht bei den Feierlichkeiten gewesen. Vielleicht steckt sie in Schwierigkeiten!\n\nLuzilla ist so mitgenommen, dass ich sie nicht alleinlassen kann. Ihr müsst an meiner Stelle gehen und die Sicherheit unserer Lady gewährleisten.\n\nWenn Ihr das für mich übernehmt, werde ich Euch auch belohnen.", sourceObjective = "Findet Lady Margarete Kronsteig in der Fahlhainkapelle.", progress = "Was habt Ihr gefunden?", completion = "Ihre Mutter hat das Attentat in Auftrag gegeben?!\n\nIch wusste, dass sie nicht damit einverstanden war, dass Luzilla einen Händler ehelicht, aber ich hätte niemals gedacht, dass sie so weit gehen würde, um es zu verhindern!\n\nIch danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50763] = { id = 50763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Bitte", description = "Ich spüre, dass meine Verbindung mit diesem Ort schwächer wird und ich muss Euch danken.\n\nDennoch möchte ich Euch um einen weiteren Gefallen bitten. Bitte bringt Luzilla den Ring, den Ihr gefunden habt. Er sollte ihren Finger schmücken und nicht meine morschen Knochen.\n\nUnd noch etwas, {class}: Sagt ihr nichts davon, was hier vorgefallen ist. Sie muss schon so viel verkraften und ich möchte sie nicht weiter belasten.", sourceObjective = "Bringt Trittwarts Ring zu Luzilla Kronsteig in der Wachmannshöhe.", progress = "Was... Was ist das?!", completion = "Das... Das ist der Ring, den Alexander mir zu unserer Vermählung geben sollte. Ich hätte nicht geglaubt, ihn je wiederzusehen...\n\nIch weiß nicht, wie Ihr ihn gefunden habt, {class}, aber mit Worten allein lässt sich meine Dankbarkeit kaum ausdrücken. Dieser Ring war das Symbol der tiefen Liebe zwischen Alexander und mir.\n\nEs ist schön, sie so noch einmal zu spüren...", sourceObjectiveStatus = "unverified-source-field" }
quests[50765] = { id = 50765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinderbetreuung" }
quests[50767] = { id = 50767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenritzergang" }
quests[50769] = { id = 50769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Sturmwind", description = "Meine Herrin ist wirklich sehr gerissen. Wenn wir Sturmwind erobern wollen, werden wir die Besten der Horde brauchen, doch der Trupp muss klein genug sein, um unbemerkt ins Herz des Allianzgebiets vorzudringen.\n\n<Nathanos mustert die versammelte Gruppe und streicht sich über das Kinn.>\n\nJa, ich kann es genau sehen.\n\nUnser weiterer Weg liegt klar vor mir. Sprecht mit mir, wenn Ihr bereit seid, die Mission des Kriegshäuptlings anzugehen, {name}.", sourceObjective = "Schließt das Szenario \"Die Flucht aus Sturmwind\" ab.", progress = "Wir dürfen den Kriegshäuptling nicht enttäuschen.", completion = "Da sind wir also. Zuldazar. Wir sollten vorerst bei Talanji und Zul bleiben. Der Kriegshäuptling wird sicher wissen wollen, wie wir weiter vorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50770] = { id = 50770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effektives Gegengift", description = "Das Mittel ist fertig. \n\nIch arbeite schnell. Hoffentlich schneller als das Skorpidgift. \n\nBringt Eurem Freund dieses Gegengift und sorgt dafür, dass er alles bis auf den letzten Tropfen schluckt. \n\nIhr werdet sehr schnell merken, ob es wirkt oder nicht.", sourceObjective = "Verabreicht Serrik das Gegengift.", completion = "Danke, dass Ihr mir das Leben gerettet habt. Ich fürchte, wir haben nicht genug Zeit, uns gebührend vorzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50771] = { id = 50771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Job für die Aufräumer", description = "Solange diese Staub aufwirbelnden Sirodingsbumse sich am Strand herumtreiben, kommen unsere Aufräumer nicht an die Vorkommen ran.\n\nEin paar Leute des Trupps wollten sich anderswo umsehen, aber es kommt gar nicht in Frage, dass wir ohne diese Steine für Gallywix hier abhauen. \n\nNur unter uns, {class}: Für die Nummer hier kriegen wir einen saftigen Gefahrenzuschlag.", sourceObjective = "Identifiziert und markiert 5 Azeritvorkommen für den Ausgrabungstrupp.", completion = "Gar nicht so übel! Der Trupp wird sich schon bald um den Rest kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[50772] = { id = 50772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdbefehl", description = "Habt Ihr all diese Irrwische bemerkt? Ich habe so etwas schon einmal gesehen, als der Dämon Archimonde von den Stichen Hunderter oder vielmehr Tausender Irrwische gefällt wurde.\n\nDas kann nur eines bedeuten: Malfurion bittet um die Hilfe seiner Ahnen.\n\nDer Kriegshäuptling ist bereits mit einem Spähtrupp zur Dunkelküste geeilt, um ihn abzufangen. Bitte, {name}... Findet den Kriegshäuptling und stellt fest, ob sie ihre Beute schon erlegt hat.\n\nWir haben das Eschental schon komplett gesichert, aber wir dürfen jetzt nicht nachlassen.", sourceObjective = "Findet Kriegshäuptling Sylvanas Windläufer an der Dunkelküste.", completion = "Ich verfolge jede Bewegung Malfurions. Der Herr des Waldes ist einer ehemaligen Waldläufergeneralin von Silbermond nicht gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50773] = { id = 50773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid ein Hai", description = "Wurdet Ihr schon mal von einem Hai gebissen? Ich schon. Viele Male. Das pikst.\n\nMurlocs überleben die Angriffe von Haien normalerweise nicht.\n\nWir können das Ritual, an das ich gedacht habe, jetzt durchführen. Lasst mich wissen, wenn Ihr vorbereitet seid.", sourceObjective = "Tötet 20 Murlocs.", completion = "Wie hat es sich angefühlt, der Angstgegner der Murlocs zu sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[50774] = { id = 50774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Bot wird zurückgelassen", description = "Ihr habt Wach-E zurückgelassen und er wurde von einem riesigen Wurm gefressen! Er hat doch so großen ideellen... und auch monetären Wert.\n\nWir lassen keinen Bot zurück!\n\nTötet diesen Wurm und holt Wach-E zurück.", sourceObjective = "Helft Wach-E.", completion = "Ihr habt Wach-E gerettet! Dafür werde ich Euch ewig dankbar sein, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50775] = { id = 50775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sand zum Strand", description = "Die Leute verbrauchen die \"Munition\" schneller, als wir sie auffüllen können! \n\nIch hab ihnen gesagt, dass wir am Strand sind und sie in einem Sandwerfer. Das kann doch nicht so schwer sein, da an Sand zu kommen!\n\nAber sie sagen, das wäre gegen die Aufräumerfahrerregeln ihres Ortsverbands.\n\nIch kapier das jedenfalls nicht.\n\nSchafft uns mehr Sand ran. Diese Sandmonster müssen voll damit sein!\n\nWir werden Euch auch ordentlich entlohnen.", sourceObjective = "Sammelt 20 Sandhaufen.", progress = "Habt Ihr den Sand zusammen?", completion = "Damit sollten wir noch ein paar Säcke füllen können. Wenn sie wieder nichts mehr haben, werden sie sich ihre Spitzhacken schnappen müssen.\n\nEin bisschen Eigenversorgung würde ihnen ganz guttun!\n\nUndankbares Geschmeiß...", sourceObjectiveStatus = "unverified-source-field" }
quests[50776] = { id = 50776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Propheten" }
quests[50777] = { id = 50777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturm erwacht", description = "Ich muss erst einmal auf Samuel aufpassen. Ich habe Angst, dass die Finsternis seinen Geist überwältigt.\n\nDie gefallenen Männer und Frauen um uns herum waren Abtrünnige des Hauses. In Weisenwall wird es noch mehr von ihnen geben.\n\nFindet sie und sagt ihnen, dass \"der Sturm erwacht\". Es hat sich herumgesprochen, wofür wir kämpfen, und wir müssen so viele wie möglich auf unsere Seite ziehen.", sourceObjective = "Ruft 12 Abtrünnige zusammen.", completion = "Ich habe gesehen, wie einige der Abtrünnigen entkommen sind. Gut, dass wir sie erreicht haben, bevor Lord Sturmsang es konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[50778] = { id = 50778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Absichten", description = "Segel... im Nebel...\n\nEin Licht tief unten... in der Finsternis.\n\nAufsteigendes Wasser... nimmt Gestalt an... der Schmerz... \n\nAHHH, DER SCHMERZ!\n\nLasst es aufhören. Lasst es aufhören. Lasst den Schmerz aufhören!", sourceObjective = "Tötet den gebundenen Gewittersturm und den bezauberten Gezeitenzorn.", completion = "Ihre Rituale werden immer tollkühner. Früher oder später werden sie etwas heraufbeschwören, das sie nicht kontrollieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[50779] = { id = 50779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang" }
quests[50780] = { id = 50780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwurgebunden", description = "Ich habe einen Eid geleistet, verdammt! Wir alle haben das.\n\nAls Lord Sturmsang die ersten Befehle gab... Nun, Ihr habt ja gesehen, was geschehen ist. Wichtig ist, dass wir den Eid unserem Volk gegenüber geleistet haben und nicht diesem Lord \"verkauft seine Seele\".\n\nHier werdet Ihr ihn nicht finden. Er befindet sich bereits tief im Innern des Schreins, und kein Außenstehender kann den Kanal lebendig überqueren...\n\nNicht ohne einen Gezeitenwächter, der den Weg freimacht.\n\n<Wiebke sieht Euch fest in die Augen.>\n\nDie Rute der Gezeiten ist der Schlüssel zur Vordertür, und sie wird hier aufbewahrt. Besorgt Ihr sie, kann ich Euch zu ihm bringen.", sourceObjective = "Besorgt die Rute der Gezeiten.", progress = "Ihr habt doch die Rute, oder nicht?", completion = "Sie erachtet Euch wohl als würdig. Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[50781] = { id = 50781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über diese Brücke müsst Ihr gehen", description = "Die Brücke, die sich hier einst erstreckte, ist der einzige Landweg zum Schrein. \n\nWie es scheint, hat Lord Sturmsang sie uns versperrt, um sich mehr Zeit zu verschaffen. Wir haben bislang erfolglos versucht, uns den Weg wieder zu eröffnen.\n\nAllerdings könnte die Rute der Gezeiten, die Ihr beschafft habt, sich als Lösung unseres Problems erweisen. Gezeitenwächterveteranen benutzen sie als eine Art Schlüssel, um den Pfad der Stürme über diese gefährlichen Gewässer freizuhalten.\n\nWir werden das Ritual ein weiteres Mal beginnen... wenn Ihr die Rute führt.", sourceObjective = "Nutzt die Rute der Gezeiten, um den Pfad der Stürme zu öffnen.", progress = "Da Lord Sturmsang nun unsere Absichten kennt, kommt es auf jede Sekunde an.", completion = "Endlich steht uns der Weg offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50782] = { id = 50782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was man sich so erzählt" }
quests[50783] = { id = 50783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abyssische Rat", description = "Es gibt einen Gezeitenrat, der Lord Sturmsang untersteht. Jedes Mitglied beaufsichtigt einen anderen Bereich des Ordens.\n\nWellensprecher Raik unterrichtet Initianden in der ältesten Form der Magie der Gezeitenweisen, in der Zwiesprache mit dem Meer.\n\nDiese Tode hat er zu verantworten. Wir müssen ihn ausschalten.", sourceObjective = "Tötet Wellensprecher Raik.", completion = "Nun, jetzt weiß Lord Sturmsang auf jeden Fall von unserer Gegenwart.", sourceObjectiveStatus = "unverified-source-field" }
quests[50784] = { id = 50784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge des Sturms", description = "Wenn Lord Sturmsang Euch bisher noch nicht bemerkt hat, dann hat er es jetzt ganz sicher. Am besten, Ihr stellt ihn am Schrein des Sturms, bevor sich noch mehr seiner Anhänger zu seinem Schutz zurückfallen lassen.\n\nIch kann Euch hineinbringen, aber Ihr müsst mich dabei beschützen. Ich bin nicht in der Verfassung, noch mehr von diesen Unholden zu widerstehen.\n\nUnd versucht, Euch bedeckt zu halten. Je näher wir an den Schrein kommen, desto mehr Macht steht Lord Sturmsang zur Verfügung.", sourceObjective = "Eskortiert Gezeitenwächterin Wiebke.", completion = "Das ist der einzige Weg in den Schrein des Sturms.", sourceObjectiveStatus = "unverified-source-field" }
quests[50786] = { id = 50786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'was Rache" }
quests[50787] = { id = 50787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen öffnen", description = "Für Katherine war Priscilla Aschenwind lange Jahre eine gute Beraterin und enge Freundin. Und zwar schon, bevor sie beide ihre Ehemänner in Theramore verloren haben.\n\nWie alle anderen hat auch sie die Gerüchte über Aschenwind gehört. Aber aus Angst oder aus Loyalität hat sie sie ignoriert.\n\nEs ist an der Zeit, ihr die Augen zu öffnen.", sourceObjective = "Erzählt Katherine Prachtmeer von Lady Aschenwinds Verrat.", completion = "Mist! Wo ist sie hin?!", sourceObjectiveStatus = "unverified-source-field" }
quests[50788] = { id = 50788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gegner in den eigenen Reihen", description = "Wir müssen Katherine in Sicherheit bringen.\n\nHelft uns, einige dieser Verräter auszuschalten!", sourceObjective = "Tötet 6 Aschenwindkämpfer am Platz der Einheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50789] = { id = 50789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Luft", description = "Priscilla scheint einen Plan in der Hinterhand gehabt zu haben. Ihre Wachen haben eine Art Rauchwand erzeugt, um ihr die Flucht zu ermöglichen.\n\nBeseitigt diesen Rauch, damit die Zivilisten fliehen und wir das Gebiet sichern können!", sourceObjective = "Vernichtet 4 rauchende Ladungen am Platz der Einheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50790] = { id = 50790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsjagd", description = "Priscilla reitet uns davon! Schnappt Euch eins der Rösser und verfolgt sie!", sourceObjective = "Besteigt ein Prachtmeerstreitross und verfolgt Priscilla Aschenwind.", completion = "Ich weiß nicht, wie jemand so einen Sturz überleben könnte.\n\nWir sollten trotzdem wachsam bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50791] = { id = 50791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skrii...", description = "<Kua'fon ruht mit dem Kopf unter der Schwinge.>\n\nSkrii...\n\n<Vielleicht braucht der kleine Kerl nur ein Zeichen der Zuneigung, um wieder Mut zu fassen.>", sourceObjective = "Besänftigt Kua'fon, indem Ihr ihn auf den Arm nehmt.", completion = "<Kua'fon reibt sein Gesicht gegen Eure Hand.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50792] = { id = 50792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestechungen" }
quests[50793] = { id = 50793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenaufruhr", description = "Das Töten des Wurms hat in den unteren Höhlen für Aufruhr gesorgt. Die Eisenfluträuber scheinen ziemlich aufgeregt zu sein. Das sollten wir lieber überprüfen.\n\nNante ist unterwegs. Ihr könnt uns nahe der Höhlen treffen.", sourceObjective = "Trefft Euch mit Nante und Moxie nahe der Höhlen.", completion = "Es sind die Eisenfluträuber! Sie haben in den Höhlen unter uns einen Schatz gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[50794] = { id = 50794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht suchen", description = "Ich muss zurück zur Arena. Razgaji wird wiss'n woll'n, was hier passiert is'. \n\nWenn Ihr müsst, könnt Ihr im Außenposten nich' zu weit von hier Zuflucht find'n.\n\nIch werd unsren Anführer wiss'n lass'n, dass Ihr kommt.\n\nPasst auf Euch auf, {name}.", sourceObjective = "Findet Razgaji im Glutsandaußenposten.", completion = "Ja, Julwaba hat mir gesagt, dass Ihr kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50795] = { id = 50795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt gibt's Ärger", description = "Dank Eurer Indizien können wir beweisen, dass Aschenwind & Co hinter dem Angriff steckt.\n\nIch hätte das lieber diskret erledigt, aber diesen Luxus können wir uns wohl nicht leisten. Schaut Euch nur um... überall Leute von Aschenwind. \n\nPriscilla hat sicher noch ein Ass im Ärmel...\n\nLasst uns etwas Verstärkung holen, bevor wir da reingehen und Aufsehen erregen.", sourceObjective = "Sprecht mit 4 Prachtmeerwachen am Platz der Einheit.", completion = "Also gut. Es ist so weit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50796] = { id = 50796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKRIIIII!", description = "<Kua'fon öffnet das Mäulchen und stößt ein langanhaltendes Kreischen aus.>\n\nSKRIIIIIIIII!!!\n\n<Ihr wisst, was zu tun ist.>", sourceObjective = "Füttert Kua'fon.", completion = "<Kua'fon leckt sich über die Lippen und seufzt zufrieden.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50797] = { id = 50797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schildkrötige Einladung", description = "Ihr wart eine große Hilfe, {race}. Bitte besucht uns und die anderen Tortollaner an der Juwelenscheinküste. \n\nWir müssen über Suppe und andere dringende Angelegenheiten sprechen.", sourceObjective = "Besucht Maokka und die anderen Tortollaner an der Juwelenscheinküste.", completion = "Ihr kommt zur rechten Zeit. Wir könnten Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50798] = { id = 50798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch hinaus", description = "Ah, da seid Ihr ja.\n\nKua'fon is' in den Dschungel gelauf'n. Ich sah ihn den westlich'n Pfad aus dem Kral rauslauf'n, aber dann hab ich ihn aus den Augen verlor'n.\n\nSo is' das mit den jungen Wilden. Unsre geflügelt'n Begleiter haben 'nen ausgeprägten Sinn fürs Abenteuer!\n\nWär gut, wenn Euer Kleiner flieg'n könnt, aber er is' noch nich' so weit. Als Erstes würd ich alle halbwegs hoch gelegenen Plätze absuch'n, zu denen er hinaufklettern könnte.", sourceObjective = "Findet und rettet Kua'fon im Tümpel.", completion = "<Kua'fon wirkt mächtig zufrieden mit sich selbst.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50800] = { id = 50800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wälder", description = "Vorsicht, {name}. Im Wald wimmelt es noch immer vor Sturmgrimms Truppen...\n\nPasst auf, was hinter Euch passiert!", sourceObjective = "Schlagt den Hinterhalt der Allianz zurück.", completion = "Malfurion wird bald mit einer Armee zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[50801] = { id = 50801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für Ptrobleme", description = "Ah, ja, ich hab mich schon gefragt, wann Ihr wohl nach Eurem Kleinen seh'n kommt.\n\nWie Ihr sicher bemerkt habt, is' er nich' hier. Die Kleinen sind ziemlich neugierig un' verlass'n oft das Nest, bevor sie bereit dazu sind. Meistens is' es die Aufgabe der Brutmutter, sie vom Ausbüx'n abzuhalt'n.\n\nWas? Habt Ihr gedacht, ich würd ihn aufhalt'n?\n\n<Schwingenhalter Goja lacht.>\n\nAusm Westen hab ich Gekreische gehört. Beeilt Euch lieber, sonst gibt's vielleicht kein Junges mehr, auf das Ihr aufpass'n könnt!", sourceObjective = "Findet Kua'fon im Tümpel und rettet ihn vor Gefahren.", completion = "<Kua'fon lässt tief aus seiner Kehle ein leises Geräusch ertönen. Er wirkt sehr zufrieden mit sich selbst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50802] = { id = 50802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenebbe", description = "Vor einigen Jahren wollte ich mich den Eisenfluträubern anschließen, aber sie meinten nur, ich sei nicht aus dem richtigen \"Eisenflutholz\" geschnitzt, nicht grausam und herzlos genug!\n\nAlso hab ich mich mit Nante und Moxie hier in der Totenschwemme zusammengetan. Wir haben dann selbst angefangen, nach Schätzen zu suchen.\n\nLasst uns diesen Eisenflutmemmen zeigen, dass sie nicht aus dem richtigen \"Totenschwemmholz\" geschnitzt sind.", sourceObjective = "Tötet 10 Eisenfluträuber.", completion = "Niemand wird ein paar Räubern auch nur eine Träne nachweinen. Vielleicht lege ich deswegen sogar ein Tänzchen hin!", sourceObjectiveStatus = "unverified-source-field" }
quests[50803] = { id = 50803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will alles und ich will es jetzt", description = "Die Eisenfluträuber glauben wohl, sie könnten einfach kommen und sich den Schatz schnappen, dem wir schon seit Monaten hinterherjagen!\n\nRechtlich gesehen gehört der Schatz uns, also geht hinein und holt uns unseren Anteil, bevor alles weg ist.\n\nUnd mit \"Anteil\" meine ich alles davon!", sourceObjective = "Sammelt 12 Schatzbeutel der Eisenfluträuber.", progress = "Ich will jedes einzelne Stück dieses Schatzes da drinnen.", completion = "Ich werde ein reicher Mann sein! Ihr verheimlicht mir doch nichts, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[50805] = { id = 50805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsruferstilllegung" }
quests[50808] = { id = 50808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fall des Imperiums aufhalten", description = "Nazmir hat ein Problem nach dem andern, {name}. Wie könnt's noch schlimmer kommen als 'n Alter Gott, der versucht, wieder an die Macht zu gelang'n?\n\nIch werd zurück nach Zul'jan reis'n, um den Schutz von Nazmir sicherzustell'n.\n\nIhr solltet nach Zuldazar zurückkehr'n un' Baine bericht'n, was hier vor sich geht. Vielleicht gefällt's ihm ja hier im Tiefenpfuhl, wer weiß?\n\nWenn Ihr wollt, kann ich Euch hier hinaus und nach Zul'jan bring'n.", sourceObjective = "Sprecht mit Baine Bluthuf in Zuldazar.", completion = "Im Sumpf lauert also ein Alter Gott, der kaum noch unter Kontrolle zu halten ist?\n\nUnglaublich! Prinzessin Talanji hatte recht damit, ihren Vater einen Narren zu nennen. Wie konnte er so ein Ding so nah an seinem Reich dulden?\n\nIch werde dafür sorgen, dass der Kriegshäuptling von Eurem Sieg... und von unserem neuen Problem erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50810] = { id = 50810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrecht ihre Ketten", description = "Ein Käpt'n der Eisenfluträuber namens \"Klaas Mekkel\" versucht schon seit Tagen, uns Angst einzujagen, aber das klappt nicht.\n\nEr hat seinen Männern befohlen, uns alle einzusperren und als Sklaven zu verkaufen! Sie haben genug Ketten für alle mitgebracht!\n\nZerbrecht die Ketten und befreit unsere Arbeiter.", sourceObjective = "Befreit 10 Arbeiter.", completion = "Da alle befreit sind, können wir uns jetzt wieder daranmachen, den Schatz zu suchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50812] = { id = 50812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwachte Elemente", description = "Anscheinend hat dieses infernalische Dröhnen und Hämmern... irgendetwas... aufgeschreckt.\n\nIch habe aus dieser Richtung Schreie gehört.\n\n<Er deutet vage in Richtung Norden.>\n\nWenn Ihr Euch um die Sache kümmern könntet, wäre ich Euch wirklich sehr verbunden.", sourceObjective = "Untersucht die Störung.", completion = "Viel besser. Wie sollen wir denn Gewinn machen, wenn wir ständig die Arbeiter ersetzen müssen?", sourceObjectiveStatus = "unverified-source-field" }
quests[50813] = { id = 50813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frachtrückforderung" }
quests[50814] = { id = 50814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schrecklicher Ort", description = "Was für eine schreckliche Stadt voller schrecklicher Leute. Alles, was sie interessiert, ist Geld! Keiner hat Mitleid mit den Schildkröten!\n\nDie Schildkröten da draußen haben Durst, trocknen aus und werden von Monstern zertrampelt!\n\nIhr müsst die Schildkröten für mich retten!", sourceObjective = "Sammelt 6 Nasspanzerschildkröten ein.", completion = "Sie bewegen sich noch! Emma wird so glücklich sein, dass sie noch frisch sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[50817] = { id = 50817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen bespielen", description = "Ich glaube, sie würden bestimmt gute Wächter abgeben, wenn sie älter sind... und richtig ausgebildet werden.\n\nAber einige meiner Schüler scheinen sich davongemacht zu haben. Es gibt so viele Dinge in der Nähe, die ihnen schaden könnten.\n\nBei all den umherirrenden Sandstürmen und wütenden Pflanzen... fand ich es sicherer, mich hier zu verstecken und nachts weiterzusuchen.\n\nIch bin völlig erledigt! \n\nWürdet Ihr diese Flöte mitnehmen und eine kleine Melodie spielen? Das wird sie daran erinnern, zu mir zurückzukommen.", sourceObjective = "Schickt 15 Kobras zu Jenoh.", completion = "Ja! Danke, {name}! Sie sind jetzt viel glücklicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[50818] = { id = 50818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verlorene Flöte", description = "<Die kleine Flöte ist zwar etwas angestaubt, aber ansonsten in einem guten Zustand.\n\nDer Besitzer kann nicht allzu weit weg sein.>", sourceObjective = "Findet den Besitzer der Wüstenflöte.\n\nBereitgestellter Gegenstand:", completion = "Meine Flöte! Ich habe überall danach gesucht!\n\nNa ja, mehr oder weniger...", sourceObjectiveStatus = "unverified-source-field" }
quests[50823] = { id = 50823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erntereif", description = "Die Kaldorei haben unseren Vormarsch doch noch stoppen können. Im günstigsten Fall wären wir bis Auberdine vorgedrungen und hätten Teldrassil eingenommen, bevor sie uns auch nur hätten verlangsamen können. Aber es spielt auch so kaum eine Rolle.\n\nMalfurion wird versuchen, uns aufzuhalten, bis seine Flotte aus Silithus zurückgekehrt ist. Bis dahin wäre seine Armee für uns kein Problem. Könnten wir doch nur einen Weg durch diese verdammten Irrwische finden.\n\nIch habe eine Idee. Lasst uns mit Saurfang sprechen.", sourceObjective = "Trefft Euch mit Saurfang und Sylvanas im Außenposten von Zoram'gar.", completion = "Die Kaldorei haben damit begonnen, ihre Präsenz an der Dunkelküste auszubauen. Damit wird es für uns schwieriger als erwartet, nach Teldrassil zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50824] = { id = 50824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Sturms", description = "Ich zweifle nicht daran, dass er unsere Gegenwart spüren kann, doch solange Lord Sturmsang seinen Zauber aufrechterhält, ist der erste Zug unser.\n\nWir haben ihn umzingelt, wie eine solche Ratte es verdient. Wir müssen dem gemeinsam ein Ende setzen.", sourceObjective = "Stellt Lord Sturmsang.", completion = "Samuel war ein anständiger Kerl mit gutem Herzen. Ein Narr... aber unser Narr.", sourceObjectiveStatus = "unverified-source-field" }
quests[50825] = { id = 50825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein des Sturms: Geflüster aus der Tiefe", description = "Wir dürfen nicht zulassen, dass Lord Sturmsang sein Werk vollendet.\n\nWenn er die Flotte Azshara ausliefert, wird ganz Kul Tiras angreifbar sein. Es werden unzählige Unschuldige sterben... oder noch schlimmer.\n\nWir können nicht mehr warten, bis die Sturmwacht auftaucht. Wir müssen das jetzt zu Ende bringen. Um alle zu schützen, die in diesem Tal zu Hause sind.\n\nWir bringen das für Samuel zu Ende.", sourceObjective = "Besiegt Lord Sturmsang im Schrein des Sturms.", completion = "Ich bete nur, dass wir nicht zu spät sind. Die Flotte muss nach Hause zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[50834] = { id = 50834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhe da unten!", description = "Diese dreckigen Mechs da unten am Strand machen eine Menge Lärm und Licht. Kein Wunder, dass meine frisch geschlüpften Jungen so mieser Laune sind!\n\nSie lassen eine Küste erbeben, die ohnehin schon instabil ist. Man weiß nie, was einen beim Aufwachen erwartet!\n\nSagt ihnen, sie sollen vorsichtig sein.", sourceObjective = "Warnt die Goblins vor der Gefahr.", completion = "Gefahr? Gewalt? Als ob wir das nicht schon wüssten!\n\nWir gehen nirgendwo hin, bevor wir nicht haben, wofür wir gekommen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[50835] = { id = 50835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hafen von Zandalar", description = "König Rastakhan hat mir befohl'n, den Hafen von Zandalar zu erkunden. Prinzessin Talanjis Vorwurf, General Jakra'zet hätt nich' ordentlich für die Sicherheit unseres Königreichs gesorgt, is' 'ne schwere Anschuldigung.\n\nIch möcht deswegen, dass Ihr mitkommt und mir Eure Sicht <eines/einer> Außenstehenden schildert. Trefft mich am Großen Basar, wenn Ihr bereit seid.", sourceObjective = "Trefft Zolani am Großen Basar.", completion = "Machen wir uns 'ran.", sourceObjectiveStatus = "unverified-source-field" }
